import { defineConfig } from 'vite';

// GitHub Pages serves this project from /<repo>/, not from the domain root, so
// every asset URL needs that prefix. Local dev still runs from '/'.
const REPO = 'ImADragon_onepromptcode_game';

// `vite preview` reports command === 'serve', so checking command alone would
// serve the built site from '/' while its HTML points at '/<repo>/' — a 404 that
// only shows up after deploying. isPreview keeps preview honest to production.
export default defineConfig(({ command, isPreview }) => ({
  base: command === 'build' || isPreview ? `/${REPO}/` : '/',
  build: {
    outDir: 'dist',
    assetsDir: 'assets',
    // three + postprocessing are genuinely large; the warning is noise here.
    chunkSizeWarningLimit: 1600,
    target: 'es2022',
  },
  server: {
    port: 5173,
  },
}));
