    }
    return true;
  }

  _kill(e, dmgKind) {
    e.alive = false;
    e.deadTime = 0;
    setState(e, 'dead');
    this.fx?.burst(e.position, e.markColor, new THREE.Color(0xffffff), 18, 1, e.rnd);
    this.fx?.ring(e.position, e.markColor, 2.6, 0.4);
    this.fx?.shake(0.18);

    // Gate bookkeeping: the last guard falling unlocks the egg it was guarding.
    if (e.gateSite) {
      const gate = this._gates.get(e.gateSite);
      if (gate) {
        gate.remaining--;
        if (gate.remaining <= 0) {
          this.ctx.events.emit('egg:unlock', { index: gate.egg });
          this._gates.delete(e.gateSite);
        }
      }
    }

    this.ctx.events.emit('enemy:die', {
      enemy: e,
      kind: e.kind,
      position: e.position.clone(),
      gems: e.tune.gems,
      cause: dmgKind,
    });
  }

  /** Called by Combat. Returns everything that actually took the hit. */
  damageAt(position, radius, kind) {
    const hit = [];
    for (const e of this.list) {
      if (!e.alive) continue;
      const dy = Math.abs(e.position.y - position.y);
      if (dy > radius + e.meta.height) continue;
      const dx = e.position.x - position.x;
      const dz = e.position.z - position.z;
      if (dx * dx + dz * dz <= (radius + e.radius) * (radius + e.radius)) {
        if (e.hitBy(kind)) hit.push(e);
      }
    }
    return hit;
  }

  update(dt, ctx) {
    const camPos = ctx.engine.camera.position;
    for (const e of this.list) {
      if (e.despawned) continue;

      e.iframes = Math.max(0, e.iframes - dt);
      stepEnemy(e, dt, ctx);

      e.group.position.copy(e.position);
      e.group.rotation.y = e.yaw;

      // Animation speed tracks actual ground speed so feet don't skate.
      if (e.currentName === 'walk' || e.currentName === 'run' || e.currentName === 'flee') {
        const base = e.currentName === 'walk' ? e.tune.speed : e.tune.chaseSpeed;
        e.current.timeScale = clamp(e.locomotion / Math.max(0.6, base), 0.35, 1.8);
      }

      // Hit flash, driven through the material's shared tint uniform.
      const u = e.mesh.material.userData?.u?.uHit;
      if (u) {
        const flash = e.iframes > 0 ? Math.min(1, e.iframes * 3.2) : 0;
        u.value.set(1, 0.55, 0.5, flash * 0.75);
      }

      // Only tick mixers for things near enough to see.
      const d2 = e.position.distanceToSquared(camPos);
      if (d2 < 90 * 90) e.mixer.update(dt);
      else if (d2 < 200 * 200) e.mixer.update(dt * 0.5);
    }

    this.fx?.update(dt, ctx);
    this.projectiles?.update?.(dt, ctx);
  }

  dispose() {
    for (const e of this.list) {
      e.mixer.stopAllAction();
      e.mixer.uncacheRoot(e.mesh);
      e.skeleton?.dispose();
      e.group.removeFromParent();
    }
    this.list.length = 0;
    for (const arch of this._archetypes.values()) arch.geometry?.dispose();
    this._archetypes.clear();
    for (const m of this._materials.values()) m.dispose();
    this._materials.clear();
    this._gates.clear();
    this.fx?.dispose();
    this.projectiles?.dispose?.();
    this.group.clear();
  }
}

