/** A sampleGround() result that every move is allowed onto. */
function groundAt(y = 0, extra = {}) {
  return { y, islandId: 1, u: 0.1, slope: 0, normal: new THREE.Vector3(0, 1, 0), ...extra };
}

function makeEnemy(overrides = {}) {
  const tune = { ...TUNING.gnorc, ...(overrides.tune || {}) };
  const meta = { height: 1.6, ...(overrides.meta || {}) };

  const e = {
    kind: 'gnorc',
    tune,
    meta,
    group: { visible: true },
    position: new THREE.Vector3(0, 0, 0),
    home: new THREE.Vector3(0, 0, 0),
    target: new THREE.Vector3(0, 0, 0),
    knock: new THREE.Vector3(),
    alive: true,
    state: 'patrol',
    stateTime: 0,
    deadTime: 0,
    cooldown: 0,
    struck: false,
    diveTime: 0,
    locomotion: 0,
    yaw: 0,
    phase: 0,
    groundY: 0,
    wanderTime: 5,
    rnd_speed: 1,
    homeIsland: 1,
    markColor: new THREE.Color(0xabcdef),
    despawned: false,
    rnd: { range: jest.fn(() => 0.5) },
    onState: jest.fn(),
  };

  Object.assign(e, overrides);
  e.tune = tune;
  e.meta = meta;
  if (!overrides.rnd) e.rnd = { range: jest.fn(() => 0.5) };
  return e;
}

function makeCtx({ player = new THREE.Vector3(0, 0, 0), sampleGround, ...overrides } = {}) {
  return {
    player: { position: player },
    world: { sampleGround: sampleGround || jest.fn(() => groundAt()) },
    engine: { camera: { quaternion: new THREE.Quaternion() } },
    controller: { hurt: jest.fn() },
    projectiles: { fire: jest.fn() },
    enemyFx: { pushMark: jest.fn() },
    time: 0,
    ...overrides,
  };
}

const statesSeen = (e) => e.onState.mock.calls.map(([next]) => next);

// ---------------------------------------------------------------------------
// Dead enemies
// ---------------------------------------------------------------------------

describe('dead enemies', () => {
  test('settle toward the ground and then hide and despawn after 1.1s', () => {
    const e = makeEnemy({
      alive: false,
      state: 'dead',
      deadTime: 1.0,
      groundY: 0,
      position: new THREE.Vector3(3, 5, 4),
    });
    const ctx = makeCtx();

    stepEnemy(e, 0.09, ctx);

    expect(e.deadTime).toBeCloseTo(1.09, 10);
    expect(e.position.x).toBe(3);
    expect(e.position.z).toBe(4);
    expect(e.position.y).toBeGreaterThan(0);
    expect(e.position.y).toBeLessThan(5);
    expect(e.group.visible).toBe(true);
    expect(e.despawned).toBe(false);
    // The dead branch returns before movement, cooldown and ground sampling.
    expect(ctx.world.sampleGround).not.toHaveBeenCalled();
    expect(ctx.controller.hurt).not.toHaveBeenCalled();
    expect(e.cooldown).toBe(0);

    stepEnemy(e, 0.02, ctx); // 1.11s dead — past the despawn threshold

    expect(e.deadTime).toBeCloseTo(1.11, 10);
    expect(e.group.visible).toBe(false);
    expect(e.despawned).toBe(true);
  });

  test('does not mark an already hidden corpse as newly despawned', () => {
    const e = makeEnemy({
      alive: false,
      state: 'dead',
      deadTime: 2,
      groundY: 0,
