function clips(rig) {
  const mix = (...o) => Object.assign({}, ...o);
  const stand = {
    thighL: [4, 0, -6], shinL: [-8, 0, 0], footL: [5, 0, 0],
    thighR: [4, 0, 6], shinR: [-8, 0, 0], footR: [5, 0, 0],
    shoulderL: [0, 0, 6], armL: [-6, 0, 16], foreL: [-22, 0, 10],
    shoulderR: [0, 0, -6], armR: [-6, 0, -16], foreR: [-22, 0, -10],
    neck: [6, 0, 0], head: [-4, 0, 0],
  };
  const out = {};

  // idle — slow bellows breathing, plates settling, occasional shoulder roll.
  const idlePose = (ph) => {
    const s = Math.sin(ph);
    return mix(stand, {
      hips: [0, s * 1.5, s * 1.5],
      spine: [-s * 1.5, 0, 0],
      chest: [-3 + s * 2.5, s * 2, 0],
      neck: [6 - s * 2, -s * 3, 0],
      head: [-4 + s * 2, -s * 5, 0],
      shoulderL: [-s * 4, 0, 6 + s * 5],
      shoulderR: [-s * 4, 0, -6 - s * 5],
      armL: [-6 + s * 3, 0, 16], armR: [-6 + s * 3, 0, -16],
      stackL: [s * 4, 0, 0], stackR: [-s * 4, 0, 0],
    });
  };
  out.idle = rig.clip('idle', 4.0, [
    { t: 0, pose: idlePose(0), pos: { root: [0, 0, 0] } },
    { t: 1.0, pose: idlePose(Math.PI * 0.5), pos: { root: [0, 0.014, 0] } },
    { t: 2.0, pose: idlePose(Math.PI), pos: { root: [0, 0, 0] } },
    { t: 3.0, pose: idlePose(Math.PI * 1.5), pos: { root: [0, 0.01, 0] } },
    { t: 4.0, pose: idlePose(Math.PI * 2), pos: { root: [0, 0, 0] } },
  ]);

  // walk — slow, planted, whole body rocks. Every footfall should feel like weight.
  const gait = (name, dur, amp, lean, bob) => {
    const keys = [];
    const N = 8;
    for (let i = 0; i <= N; i++) {
      const ph = (i / N) * Math.PI * 2;
      const s = Math.sin(ph);
      // Sharp landing: the body drops on each plant rather than riding a sine.
      const plant = Math.pow(Math.abs(Math.cos(ph)), 3);
      keys.push({
        t: (i / N) * dur,
        pose: mix(stand, {
          hips: [lean * 0.3, s * 6, s * 7],
          spine: [-lean * 0.4, -s * 3, -s * 4],
          chest: [-lean, s * 5, -s * 4],
          neck: [6, -s * 3, 0],
          head: [-4, -s * 3, s * 2],
          thighL: [amp * s + 6, 0, -7],
          shinL: [-12 - Math.max(0, Math.sin(ph + 1.3)) * amp * 0.8, 0, 0],
          footL: [6 + s * amp * 0.3, 0, 0],
          thighR: [-amp * s + 6, 0, 7],
          shinR: [-12 - Math.max(0, Math.sin(ph + Math.PI + 1.3)) * amp * 0.8, 0, 0],
          footR: [6 - s * amp * 0.3, 0, 0],
          shoulderL: [-s * 6, 0, 8], armL: [-s * 12 - 6, 0, 18], foreL: [-26, 0, 12],
          shoulderR: [s * 6, 0, -8], armR: [s * 12 - 6, 0, -18], foreR: [-26, 0, -12],
        }),
        pos: { root: [0, bob * (1 - plant) - 0.02 * plant, 0] },
      });
    }
    return rig.clip(name, dur, keys);
  };
  out.walk = gait('walk', 1.5, 22, 4, 0.05);
  out.run = gait('run', 0.95, 32, 12, 0.07);

  // alert — no startle. It squares up, cranks the visor toward you, vents flare.
  out.alert = rig.clip(
    'alert',
    1.0,
    [
      { t: 0, pose: mix(stand, {}), pos: { root: [0, 0, 0] } },
      {
        t: 0.3,
        pose: mix(stand, {
          spine: [4, 0, 0], chest: [6, 0, 0], neck: [-2, 0, 0], head: [-14, 0, 0],
          shoulderL: [-14, 0, 20], armL: [-16, 0, 26], shoulderR: [-14, 0, -20], armR: [-16, 0, -26],
          thighL: [8, 0, -10], thighR: [8, 0, 10],
