        if (y > 1.25 && y < 1.65) shoulderSpan = Math.max(shoulderSpan, x);
        if (y > 1.9) helmetSpan = Math.max(helmetSpan, x);
        if (y > 0.8 && y < 1.1) hipSpan = Math.max(hipSpan, x);
      });

      expect(shoulderSpan).toBeGreaterThan(0.6);
      expect(shoulderSpan).toBeGreaterThan(hipSpan * 1.5);
