  describe('determinism and isolation', () => {
    it('produces byte-identical geometry for repeated builds', () => {
      const second = buildBrute();
      expect(vertexCount(second.geometry)).toBe(vertexCount(build.geometry));

      for (const name of attributeNames) {
        expect(Array.from(attribute(second.geometry, name).array))
          .toEqual(Array.from(attribute(build.geometry, name).array));
      }
      expect(Array.from(second.geometry.index.array)).toEqual(Array.from(build.geometry.index.array));

      expect(Object.keys(second.clips)).toEqual(Object.keys(build.clips));
      for (const name of Object.keys(build.clips)) {
        expect(second.clips[name].duration).toBe(build.clips[name].duration);
        expect(second.clips[name].tracks.length).toBe(build.clips[name].tracks.length);
      }
    });

    it('hands back independent geometry and rig objects per build', () => {
      const second = buildBrute();
      expect(second.geometry).not.toBe(build.geometry);
      expect(attribute(second.geometry, 'position').array)
        .not.toBe(attribute(build.geometry, 'position').array);
      expect(second.rig).not.toBe(build.rig);
      expect(second.rig.names).not.toBe(build.rig.names);

      const original = attribute(build.geometry, 'position').getX(0);
      attribute(build.geometry, 'position').array[0] += 100;
      expect(attribute(second.geometry, 'position').getX(0)).toBeCloseTo(original, 6);
    });
  });

  describe('animation clips', () => {
    const expectedDurations = {
      idle: 4,
      walk: 1.5,
      run: 0.95,
      alert: 1,
      attack: 1.25,
      stomp: 1.1,
      hurt: 0.42,
      die: 1.35,
      taunt: 1,
    };

    it('provides the full combat animation set', () => {
      expect(Object.keys(build.clips).sort()).toEqual(Object.keys(expectedDurations).sort());
      for (const [name, duration] of Object.entries(expectedDurations)) {
        const clip = build.clips[name];
        expect(clip).toBeInstanceOf(THREE.AnimationClip);
        expect(clip.name).toBe(name);
        expect(clip.duration).toBeCloseTo(duration, 6);
        expect(clip.tracks.length).toBeGreaterThan(0);
      }
    });

    it('reuses the alert clip as the taunt, while every other clip is distinct', () => {
      expect(build.clips.taunt).toBe(build.clips.alert);
      const distinct = new Set(Object.values(build.clips));
      expect(distinct.size).toBe(Object.keys(build.clips).length - 1);
    });

    it('sets looping semantics: locomotion repeats and combat actions play once', () => {
      for (const name of ['idle', 'walk', 'run']) {
        expect(build.clips[name].userData.loop).toBe(THREE.LoopRepeat);
      }
      for (const name of ['alert', 'attack', 'stomp', 'hurt', 'die', 'taunt']) {
        expect(build.clips[name].userData.loop).toBe(THREE.LoopOnce);
      }
    });

    it('binds every track to an existing bone and valid keyframe times', () => {
      const boneNames = new Set(build.rig.names);
      for (const [clipName, clip] of Object.entries(build.clips)) {
        for (const track of clip.tracks) {
          const [boneName, property] = track.name.split('.');
          expect(boneNames.has(boneName)).toBe(true);
          expect(['quaternion', 'position', 'scale']).toContain(property);
          expect(track.times.length).toBeGreaterThan(1);
          expect(track.times.length).toBe(track.values.length / track.getValueSize());
          expect(track.times[0]).toBe(0);
          expect(track.times[track.times.length - 1]).toBeCloseTo(clip.duration, 6);

          for (let i = 1; i < track.times.length; i++) {
            expect(track.times[i]).toBeGreaterThan(track.times[i - 1]);
          }
          for (const value of track.values) {
            expect(Number.isFinite(value)).toBe(true);
          }
        }
        expect(clip.tracks.some((track) => track.name === 'root.position')).toBe(true);
      }
    });

