      const rest = build.rig.rest.root;
      for (const clip of Object.values(build.clips)) {
        const rootTrack = clip.tracks.find((track) => track.name === 'root.position');
        expect(rootTrack).toBeDefined();
        expect(firstKey(rootTrack)).toEqual([rest.x, rest.y, rest.z]);
      }
    });

