      for (const name of ['idle', 'walk', 'run']) {
        const clip = build.clips[name];
        for (const track of clip.tracks) {
          const start = firstKey(track);
          const end = lastKey(track);
          for (let i = 0; i < start.length; i++) {
            expect(start[i]).toBeCloseTo(end[i], 5);
          }
        }
      }
    });

    it('gives the walk and run cycles a planted vertical bob', () => {
      for (const name of ['walk', 'run']) {
        const rootTrack = build.clips[name].tracks.find((track) => track.name === 'root.position');
        const ys = [];
        for (let i = 1; i < rootTrack.values.length; i += 3) ys.push(rootTrack.values[i]);
        const min = Math.min(...ys);
        const max = Math.max(...ys);
        expect(min).toBeLessThan(0);
        expect(max).toBeGreaterThan(0);
        expect(max - min).toBeGreaterThan(0.03);
      }
    });

    it('animates the exhaust stacks only in the idle breathing loop', () => {
      const trackNames = (clip) => clip.tracks.map((track) => track.name);
      expect(trackNames(build.clips.idle)).toContain('stackL.quaternion');
      expect(trackNames(build.clips.idle)).toContain('stackR.quaternion');
      expect(trackNames(build.clips.walk)).not.toContain('stackL.quaternion');
      expect(trackNames(build.clips.alert)).not.toContain('stackL.quaternion');
    });
  });
});
