import * as THREE from 'three';
import { buildBrute } from '../../../../src/actors/enemies/Brute.js';

const attributeNames = ['position', 'normal', 'color', 'aSlot', 'skinIndex', 'skinWeight'];

const attribute = (geometry, name) => geometry.getAttribute(name);
const vertexCount = (geometry) => attribute(geometry, 'position').count;

function forEachVertex(geometry, visit) {
  const pos = attribute(geometry, 'position');
  const count = pos.count;
  for (let i = 0; i < count; i++) visit(i, pos.getX(i), pos.getY(i), pos.getZ(i));
}

function collectVertices(geometry, predicate) {
  const out = [];
  const pos = attribute(geometry, 'position');
  forEachVertex(geometry, (i) => {
    if (predicate(i, pos.getX(i), pos.getY(i), pos.getZ(i))) out.push(i);
  });
  return out;
}

function trackValues(track) {
  return Array.from(track.values);
}

function firstKey(track) {
  const size = track.getValueSize();
  return Array.from(track.values.slice(0, size));
}

function lastKey(track) {
  const size = track.getValueSize();
  return Array.from(track.values.slice(track.values.length - size));
}

describe('buildBrute', () => {
  let build;

  beforeEach(() => {
    build = buildBrute();
  });

  describe('returned payload', () => {
    it('returns a rig, a buffer geometry, animation clips and archetype meta', () => {
      expect(build).toBeDefined();
      expect(build.rig).toBeDefined();
      expect(build.geometry).toBeInstanceOf(THREE.BufferGeometry);
      expect(build.clips).toBeDefined();
      expect(typeof build.clips).toBe('object');
      expect(build.meta).toBeDefined();

      expect(typeof build.rig.p).toBe('function');
      expect(Array.isArray(build.rig.names)).toBe(true);
      expect(build.rig.names.length).toBeGreaterThan(0);
    });

    it('reports the documented brute archetype metadata', () => {
      expect(build.meta).toEqual({
      expect(trackNames(build.clips.walk)).not.toContain('stackL.quaternion');
      expect(trackNames(build.clips.alert)).not.toContain('stackL.quaternion');
    });
  });
});

