let missing=0; const missingBySlot={};
for(let i=0;i<pos.count;i++){const k=key(-pos.getX(i),pos.getY(i),pos.getZ(i)); if(!set.has(k)){missing++; const s=slot.getX(i); missingBySlot[s]=(missingBySlot[s]||0)+1;}}
console.log('missing mirror',missing,missingBySlot);
// normals check
const nor=g.getAttribute('normal'); let badN=0, minLen=9,maxLen=0;
for(let i=0;i<nor.count;i++){const l=Math.hypot(nor.getX(i),nor.getY(i),nor.getZ(i)); if(!(Math.abs(l-1)<1e-4))badN++; minLen=Math.min(minLen,l);maxLen=Math.max(maxLen,l);}
console.log({badN,minLen,maxLen});
// unique colors
const cols=new Map(); for(let i=0;i<pos.count;i++){const k=[g.getAttribute('color').getX(i),g.getAttribute('color').getY(i),g.getAttribute('color').getZ(i)].join(','); cols.set(k,(cols.get(k)||0)+1);}
console.log('unique colors',cols.size,[...cols.entries()].slice(0,30));
// color by slot range
const ranges={}; for(let i=0;i<pos.count;i++){const s=slot.getX(i);const c=[g.getAttribute('color').getX(i),g.getAttribute('color').getY(i),g.getAttribute('color').getZ(i)]; if(!ranges[s])ranges[s]=[Infinity,-Infinity];for(const v of c){ranges[s][0]=Math.min(ranges[s][0],v);ranges[s][1]=Math.max(ranges[s][1],v);}}
console.log('ranges by slot',ranges);
"
"}

