/**
 * Tests for Flyer.buildFlyer().
 *
 * The function is a pure procedural factory: it assembles a bone rig, a skinned
 * BufferGeometry and a set of AnimationClips, then returns them together with
 * the archetype metadata.  The tests below observe that returned bundle only;
 * they never reach into the emitters directly.
 */
import * as THREE from 'three';
import { buildFlyer, META } from '../../../../src/actors/enemies/Flyer.js';

const BONE_NAMES = [
  'root', 'neck', 'head', 'jaw',
  'abdA', 'abdB', 'sting',
  'wingL1', 'wingL2', 'wingL3',
  'wingR1', 'wingR2', 'wingR3',
  'legL', 'footL', 'legR', 'footR',
];

const PARENTS = {
  root: null,
  neck: 'root',
  head: 'neck',
  jaw: 'head',
  abdA: 'root',
  abdB: 'abdA',
  sting: 'abdB',
  wingL1: 'root',
  wingL2: 'wingL1',
  wingL3: 'wingL2',
  wingR1: 'root',
  wingR2: 'wingR1',
  wingR3: 'wingR2',
  legL: 'root',
  footL: 'legL',
  legR: 'root',
  footR: 'legR',
};

const SLOT = { none: 0, skin: 1, cloth: 2, metal: 3, glowA: 4, glowB: 5 };

const DARK_COLOR = [0.03, 0.025, 0.035];
const FANG_COLOR = [0.6, 0.58, 0.55];

const attr = (geometry, name) => geometry.getAttribute(name);

function vertexColor(geometry, i) {
  const c = attr(geometry, 'color');
  return [c.getX(i), c.getY(i), c.getZ(i)];
}

function vertexPosition(geometry, i) {
  const p = attr(geometry, 'position');
  return [p.getX(i), p.getY(i), p.getZ(i)];
}

function dominantBone(bundle, i) {
  const si = attr(bundle.geometry, 'skinIndex');
  const sw = attr(bundle.geometry, 'skinWeight');
  let best = -1;
  let bone = -1;
  for (let k = 0; k < 4; k++) {
    const w = sw.array[i * 4 + k];
    if (w > best) {
      best = w;
      bone = si.array[i * 4 + k];
    }
  }
  return { name: bundle.rig.names[bone], index: bone, weight: best };
}

function colorMatches(geometry, i, rgb, eps = 1e-5) {
  const c = vertexColor(geometry, i);
  return c.every((v, k) => Math.abs(v - rgb[k]) <= eps);
}

function trackNamed(clip, name) {
  return clip.tracks.find((track) => track.name === name);
}

function build() {
  return buildFlyer();
}

describe('buildFlyer() bundle', () => {
  test('returns a rig, a geometry, the animation clips and metadata', () => {
    const bundle = build();

    expect(bundle).toBeDefined();
    expect(Object.keys(bundle).sort()).toEqual(['clips', 'geometry', 'meta', 'rig']);
    expect(bundle.geometry).toBeInstanceOf(THREE.BufferGeometry);
    expect(bundle.rig).toBeDefined();
    expect(typeof bundle.rig.p).toBe('function');
    expect(typeof bundle.rig.fixed).toBe('function');
    expect(typeof bundle.rig.grouped).toBe('function');
    expect(typeof bundle.rig.instantiate).toBe('function');
    expect(bundle.clips).toBeInstanceOf(Object);
  });

  test('reports the flyer archetype metadata', () => {
    const bundle = build();

    expect(bundle.meta).toBe(META);
    expect(bundle.meta).toEqual({
      kind: 'flyer',
      height: 0.6,
      radius: 0.7,
      hitHeight: 0,
      eyeHeight: 0.08,
      groundOffset: 0,
      scale: 1,
    });
  });

  test('two calls produce independent but byte-identical results', () => {
    const first = build();
    const second = build();

    expect(first.geometry).not.toBe(second.geometry);
    expect(first.rig).not.toBe(second.rig);
    expect(first.clips).not.toBe(second.clips);
    expect(first.clips.idle).not.toBe(second.clips.idle);

    for (const name of ['position', 'normal', 'color', 'aSlot', 'skinIndex', 'skinWeight']) {
      expect(Array.from(attr(first.geometry, name).array)).toEqual(
        Array.from(attr(second.geometry, name).array)
      );
    }
    expect(Array.from(first.geometry.index.array)).toEqual(Array.from(second.geometry.index.array));

    expect(Object.keys(first.clips)).toEqual(Object.keys(second.clips));
    for (const key of Object.keys(first.clips)) {
      const a = first.clips[key];
      const b = second.clips[key];
      expect(a.duration).toBe(b.duration);
      expect(a.tracks.map((t) => t.name)).toEqual(b.tracks.map((t) => t.name));
      for (let t = 0; t < a.tracks.length; t++) {
        expect(Array.from(a.tracks[t].times)).toEqual(Array.from(b.tracks[t].times));
        expect(Array.from(a.tracks[t].values)).toEqual(Array.from(b.tracks[t].values));
      }
    }
  });
});

describe('buildFlyer() rig', () => {
  test('creates the complete 17-bone flyer hierarchy', () => {
    const { rig } = build();

    expect(rig.names).toEqual(BONE_NAMES);
    expect(Object.keys(rig.boneIndex).sort()).toEqual([...BONE_NAMES].sort());
    expect(rig.boneIndex.root).toBe(0);

    const instance = rig.instantiate();
    expect(instance.bones).toHaveLength(BONE_NAMES.length);
    expect(instance.skeleton.bones).toHaveLength(BONE_NAMES.length);
    expect(instance.bones.map((bone) => bone.name)).toEqual(BONE_NAMES);
    expect(instance.root.name).toBe('root');
    expect(instance.skeleton.bones[0]).toBe(instance.root);

    for (const name of BONE_NAMES) {
      const parent = PARENTS[name];
      const bone = instance.map[name];
      expect(bone).toBeDefined();
      if (parent === null) {
        expect(bone.parent).toBe(null);
      } else {
        expect(bone.parent).toBe(instance.map[parent]);
      }
    }
  });

  test('accumulates bind-pose positions down the hierarchy', () => {
    const { rig } = build();

    expect(rig.p('root').toArray()).toEqual([0, 0, 0]);
    expect(rig.p('neck').toArray()).toEqual([0, 0.05, 0.18]);
    expect(rig.p('head').toArray()[0]).toBeCloseTo(0, 10);
    expect(rig.p('head').toArray()[1]).toBeCloseTo(0.05, 10);
    expect(rig.p('head').toArray()[2]).toBeCloseTo(0.32, 10);
    expect(rig.p('jaw').toArray()[1]).toBeCloseTo(0, 10);
    expect(rig.p('jaw').toArray()[2]).toBeCloseTo(0.36, 10);
    expect(rig.p('abdB').toArray()[1]).toBeCloseTo(-0.06, 10);
    expect(rig.p('abdB').toArray()[2]).toBeCloseTo(-0.42, 10);
    expect(rig.p('sting').toArray()[2]).toBeCloseTo(-0.59, 10);

    // The rig is laterally symmetric for wings, legs and feet.
    for (const pair of [
      ['wingL1', 'wingR1'], ['wingL2', 'wingR2'], ['wingL3', 'wingR3'],
      ['legL', 'legR'], ['footL', 'footR'],
    ]) {
      const [left, right] = pair.map((name) => rig.p(name));
      expect(left.x).toBeCloseTo(-right.x, 10);
      expect(left.y).toBeCloseTo(right.y, 10);
      expect(left.z).toBeCloseTo(right.z, 10);
    }
  });

  test('hands out independent instances without disturbing the template', () => {
    const { rig } = build();
    const first = rig.instantiate();
    const second = rig.instantiate();

    expect(first.root).not.toBe(second.root);
    expect(first.bones[0]).not.toBe(second.bones[0]);
    expect(first.skeleton.bones[0]).not.toBe(second.skeleton.bones[0]);

    const templateWing = rig.p('wingL1');
    first.map.wingL1.position.set(9, 9, 9);
    expect(second.map.wingL1.position.toArray()).toEqual([0.13, 0.12, 0.02]);
    expect(rig.p('wingL1').toArray()).toEqual(templateWing.toArray());
  });
});

describe('buildFlyer() geometry', () => {
  test('publishes a complete skinned geometry', () => {
    const { geometry } = build();

    expect(geometry.getAttribute('position').count).toBe(758);
    expect(geometry.getAttribute('position').itemSize).toBe(3);
    expect(geometry.getAttribute('normal').itemSize).toBe(3);
    expect(geometry.getAttribute('color').itemSize).toBe(3);
    expect(geometry.getAttribute('aSlot').itemSize).toBe(1);
    expect(geometry.getAttribute('skinIndex').itemSize).toBe(4);
    expect(geometry.getAttribute('skinWeight').itemSize).toBe(4);
    expect(Object.keys(geometry.attributes).sort()).toEqual([
      'aSlot', 'color', 'normal', 'position', 'skinIndex', 'skinWeight',
    ]);

    for (const name of ['normal', 'color', 'aSlot', 'skinIndex', 'skinWeight']) {
      expect(geometry.getAttribute(name).count).toBe(geometry.getAttribute('position').count);
    }

    expect(geometry.index).not.toBe(null);
    expect(geometry.index.count).toBe(3732);
    expect(geometry.index.count % 3).toBe(0);
    expect(geometry.groups).toEqual([]);
  });

  test('has only valid triangle indices and finite vertex data', () => {
    const { geometry } = build();
    const position = attr(geometry, 'position');
    const normal = attr(geometry, 'normal');
    const color = attr(geometry, 'color');
    const count = position.count;

    for (let i = 0; i < geometry.index.count; i++) {
      const idx = geometry.index.array[i];
      expect(Number.isInteger(idx)).toBe(true);
      expect(idx).toBeGreaterThanOrEqual(0);
      expect(idx).toBeLessThan(count);
    }

    for (let i = 0; i < count; i++) {
      for (const value of [...vertexPosition(geometry, i), ...vertexColor(geometry, i)]) {
        expect(Number.isFinite(value)).toBe(true);
      }
      expect(Number.isFinite(normal.getX(i))).toBe(true);
      expect(Number.isFinite(normal.getY(i))).toBe(true);
      expect(Number.isFinite(normal.getZ(i))).toBe(true);
    }
  });

  test('normalises all vertex normals and keeps colours in the lit range', () => {
    const { geometry } = build();
    const normal = attr(geometry, 'normal');
    const color = attr(geometry, 'color');

    for (let i = 0; i < normal.count; i++) {
      const length = Math.hypot(normal.getX(i), normal.getY(i), normal.getZ(i));
      expect(length).toBeCloseTo(1, 5);
    }

    for (let i = 0; i < color.count; i++) {
      for (const channel of vertexColor(geometry, i)) {
