/**
 * A bone tree plus everything needed to author geometry in its bind pose.
 * The Rig itself is a template: `instantiate()` hands out fresh bones so every
 * enemy animates independently while sharing one geometry.
 */
export class Rig {
  constructor(spec) {
    this.spec = spec;
    this.boneIndex = {};
    this.rest = {};
    this.names = [];

    const map = {};
    const bones = [];
    for (const [name, parent, off] of spec) {
      const b = new THREE.Bone();
      b.name = name;
      b.position.set(off[0], off[1], off[2]);
      map[name] = b;
      this.boneIndex[name] = bones.length;
      this.rest[name] = new THREE.Vector3(off[0], off[1], off[2]);
      this.names.push(name);
      bones.push(b);
      if (parent) map[parent].add(b);
    }
    bones[0].updateMatrixWorld(true);

    this.bindPos = {};
    for (const b of bones) this.bindPos[b.name] = new THREE.Vector3().setFromMatrixPosition(b.matrixWorld);
  }

  /** Fresh bones + skeleton for one instance. Bind space is identity. */
  instantiate() {
    const map = {};
    const bones = [];
    for (const [name, parent, off] of this.spec) {
      const b = new THREE.Bone();
      b.name = name;
      b.position.set(off[0], off[1], off[2]);
      map[name] = b;
      bones.push(b);
      if (parent) map[parent].add(b);
    }
    bones[0].updateMatrixWorld(true);
    return { root: bones[0], bones, map, skeleton: new THREE.Skeleton(bones) };
  }

  p(name) {
    return this.bindPos[name].clone();
  }

  /** Point between two bind positions. */
  mid(a, b, t = 0.5) {
    return this.bindPos[a].clone().lerp(this.bindPos[b], t);
  }

  rigid(name) {
    return [[this.boneIndex[name], 1]];
  }

  /** Weight a point to the nearest bones within `group`. */
  weightsFor(point, group, hardness = 2.6, maxBones = 2) {
    const scored = group.map((n) => ({ i: this.boneIndex[n], d: this.bindPos[n].distanceTo(point) }));
    scored.sort((a, b) => a.d - b.d);
    const out = [];
    for (let i = 0; i < Math.min(maxBones, scored.length); i++) {
      out.push([scored[i].i, 1 / Math.pow(scored[i].d + 0.05, hardness)]);
    }
    return out;
  }

  /** Curried weight function for the grid emitters. */
  grouped(group, hardness = 2.6, maxBones = 2) {
    return (p) => this.weightsFor(p, group, hardness, maxBones);
  }

  fixed(name) {
    const w = this.rigid(name);
    return () => w;
  }

  // ------------------------------------------------------------- clips ----

  /**
   * Author a clip from euler-offset keys (degrees), exactly like the dragon.
   * `key = { t, pose:{bone:[x,y,z]}, pos:{bone:[x,y,z]}, scale:{bone:s|[x,y,z]} }`
   * Any bone omitted from a key snaps back to rest for that key.
   */
  clip(name, duration, keys, loop = THREE.LoopRepeat) {
    const rotBones = new Set();
    const posBones = new Set();
    const sclBones = new Set();
    for (const k of keys) {
      if (k.pose) for (const n of Object.keys(k.pose)) rotBones.add(n);
      if (k.pos) for (const n of Object.keys(k.pos)) posBones.add(n);
      if (k.scale) for (const n of Object.keys(k.scale)) sclBones.add(n);
    }

    const tracks = [];
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();

    for (const bn of rotBones) {
      const times = [];
      const values = [];
      for (const k of keys) {
        const p = (k.pose && k.pose[bn]) || [0, 0, 0];
        e.set(p[0] * DEG, p[1] * DEG, p[2] * DEG, 'XYZ');
        q.setFromEuler(e);
        times.push(k.t);
        values.push(q.x, q.y, q.z, q.w);
      }
      tracks.push(new THREE.QuaternionKeyframeTrack(`${bn}.quaternion`, times, values));
    }

    for (const bn of posBones) {
      const rest = this.rest[bn];
      const times = [];
      const values = [];
      for (const k of keys) {
        const o = (k.pos && k.pos[bn]) || [0, 0, 0];
        times.push(k.t);
        values.push(rest.x + o[0], rest.y + o[1], rest.z + o[2]);
      }
      tracks.push(new THREE.VectorKeyframeTrack(`${bn}.position`, times, values));
    }

    for (const bn of sclBones) {
      const times = [];
      const values = [];
      for (const k of keys) {
        let s = (k.scale && k.scale[bn]) ?? 1;
        if (typeof s === 'number') s = [s, s, s];
        times.push(k.t);
        values.push(s[0], s[1], s[2]);
      }
      tracks.push(new THREE.VectorKeyframeTrack(`${bn}.scale`, times, values));
    }

    const clip = new THREE.AnimationClip(name, duration, tracks);
    clip.userData = { loop };
    return clip;
  }
}

// -------------------------------------------------------------- emitters ----

/**
 * Emit a lofted grid of points as a surface. Normals are accumulated from the
 * faces, which keeps them right no matter how hard the shape is deformed.
 *
 * grid[row][col] — rows run along the shape, cols around it.
 */
export function emitGrid(B, grid, opts = {}) {
  const {
    color = () => g(0.5),
    slot = 0,
    weights = () => [],
    wrap = true,
    capStart = false,
    capEnd = false,
    flip = false,
  } = opts;

  const rows = grid.length;
  const cols = grid[0].length;
  const normals = [];
  for (let r = 0; r < rows; r++) {
    normals.push([]);
    for (let c = 0; c < cols; c++) normals[r].push(new THREE.Vector3());
  }

  const lastCol = wrap ? cols : cols - 1;
  const accum = (r0, c0, r1, c1, r2, c2) => {
    const a = grid[r0][c0];
    const b = grid[r1][c1 % cols];
    const c = grid[r2][c2 % cols];
    _v0.subVectors(b, a);
    _v1.subVectors(c, a);
    _n.crossVectors(_v0, _v1);
    normals[r0][c0].add(_n);
    normals[r1][c1 % cols].add(_n);
    normals[r2][c2 % cols].add(_n);
  };

  for (let r = 0; r < rows - 1; r++) {
    for (let c = 0; c < lastCol; c++) {
      accum(r, c, r + 1, c, r + 1, c + 1);
      accum(r, c, r + 1, c + 1, r, (c + 1) % cols);
    }
  }

  // Fall back to a radial normal for degenerate rows (poles, pinched tips).
  const centre = new THREE.Vector3();
  let n = 0;
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) { centre.add(grid[r][c]); n++; }
  centre.multiplyScalar(1 / Math.max(1, n));

  const ids = [];
  for (let r = 0; r < rows; r++) {
    const row = [];
    for (let c = 0; c < cols; c++) {
      const p = grid[r][c];
      const nv = normals[r][c];
      if (nv.lengthSq() < 1e-10) nv.subVectors(p, centre);
      if (nv.lengthSq() < 1e-10) nv.set(0, 1, 0);
      nv.normalize();
      if (flip) nv.negate();
      row.push(B.vert(p, nv, color(r / (rows - 1 || 1), c / cols, p, nv), weights(p), slot));
    }
    ids.push(row);
  }

  for (let r = 0; r < rows - 1; r++) {
    for (let c = 0; c < lastCol; c++) {
      const cn = (c + 1) % cols;
      if (flip) B.quad(ids[r][c], ids[r][cn], ids[r + 1][cn], ids[r + 1][c]);
      else B.quad(ids[r][c], ids[r + 1][c], ids[r + 1][cn], ids[r][cn]);
    }
  }

  const cap = (rowIds, rowPts, invert) => {
    const c = new THREE.Vector3();
    for (const p of rowPts) c.add(p);
    c.multiplyScalar(1 / rowPts.length);
    const nrm = new THREE.Vector3().subVectors(c, centre).normalize();
    if (invert) nrm.negate();
    const centreId = B.vert(c, nrm, color(invert ? 0 : 1, 0.5, c, nrm), weights(c), slot);
    for (let i = 0; i < rowIds.length; i++) {
      const j = (i + 1) % rowIds.length;
      if (invert) B.tri(centreId, rowIds[j], rowIds[i]);
      else B.tri(centreId, rowIds[i], rowIds[j]);
    }
  };
  if (capStart) cap(ids[0], grid[0], !flip);
  if (capEnd) cap(ids[rows - 1], grid[rows - 1], !!flip);

  return ids;
}

/**
 * Swept tube along a polyline with parallel-transported frames.
 * `profile(t)` returns [radiusX, radiusY]; `offset(t)` optionally shifts the
 * ring in frame space so a shape can bulge to one side.
 */
export function tube(B, opts) {
  const {
    path,
    sides = 8,
    profile,
    radius = 0.1,
    up = UP,
    color,
    slot = 0,
    weights,
    capStart = false,
    capEnd = false,
    rings = null,
    offset = null,
  } = opts;

  const pts = rings ? resample(path, rings) : path;
  const N = pts.length;

  // Parallel-transport a frame down the path so the tube never spins.
  const tangents = [];
  for (let i = 0; i < N; i++) {
    const t = new THREE.Vector3();
    if (i === 0) t.subVectors(pts[1], pts[0]);
    else if (i === N - 1) t.subVectors(pts[N - 1], pts[N - 2]);
    else t.subVectors(pts[i + 1], pts[i - 1]);
    if (t.lengthSq() < 1e-9) t.set(0, 1, 0);
    tangents.push(t.normalize());
  }

  let ref = new THREE.Vector3().crossVectors(up, tangents[0]);
  if (ref.lengthSq() < 1e-6) ref.set(1, 0, 0);
  ref.normalize();

  const grid = [];
  for (let i = 0; i < N; i++) {
    const t = i / (N - 1);
    const tan = tangents[i];
    // Re-orthogonalise the carried reference against the new tangent.
    ref = ref.clone().addScaledVector(tan, -ref.dot(tan));
    if (ref.lengthSq() < 1e-6) {
      ref = new THREE.Vector3().crossVectors(up, tan);
      if (ref.lengthSq() < 1e-6) ref.set(1, 0, 0);
    }
    ref.normalize();
    const bi = new THREE.Vector3().crossVectors(tan, ref).normalize();

    let rx = radius;
    let ry = radius;
    if (profile) {
      const r = profile(t, i);
      if (Array.isArray(r)) { rx = r[0]; ry = r[1]; } else { rx = r; ry = r; }
    }
    const off = offset ? offset(t, i) : null;

    const row = [];
    for (let s = 0; s < sides; s++) {
      const a = (s / sides) * Math.PI * 2;
      const p = pts[i].clone()
        .addScaledVector(ref, Math.cos(a) * rx)
        .addScaledVector(bi, Math.sin(a) * ry);
      if (off) p.addScaledVector(ref, off[0]).addScaledVector(bi, off[1]);
      row.push(p);
    }
    grid.push(row);
  }

  return emitGrid(B, grid, { color, slot, weights, wrap: true, capStart, capEnd });
}

function resample(path, count) {
  const curve = new THREE.CatmullRomCurve3(path, false, 'centripetal', 0.4);
  const out = [];
  for (let i = 0; i < count; i++) out.push(curve.getPointAt(i / (count - 1)));
  return out;
}

/**
 * Deformable ellipsoid. `deform(p, dir, u, v)` may move the point freely;
 * normals are recovered from the resulting surface.
 */
export function blob(B, opts) {
  const {
    center,
    radius,
    segU = 12,
    segV = 8,
    color,
    slot = 0,
    weights,
    deform = null,
  } = opts;
  const r = Array.isArray(radius) ? radius : [radius, radius, radius];

  const grid = [];
  for (let v = 0; v <= segV; v++) {
    const phi = (v / segV) * Math.PI;
    const row = [];
    for (let u = 0; u < segU; u++) {
      const th = (u / segU) * Math.PI * 2;
      const dir = new THREE.Vector3(
        Math.sin(phi) * Math.cos(th),
        Math.cos(phi),
        Math.sin(phi) * Math.sin(th)
      );
      const p = new THREE.Vector3(center.x + dir.x * r[0], center.y + dir.y * r[1], center.z + dir.z * r[2]);
      if (deform) deform(p, dir, u / segU, v / segV);
      row.push(p);
    }
    grid.push(row);
  }
  return emitGrid(B, grid, { color, slot, weights, wrap: true });
}

/**
 * Superellipse ring — the workhorse cross-section. `exp` near 1 is an ellipse,
 * near 0.5 a rounded box. Chunky characters want rounded boxes.
 */
function superRing(sides, ru, rv, exp, out) {
  for (let s = 0; s < sides; s++) {
    const a = (s / sides) * Math.PI * 2;
    const cu = Math.cos(a);
    const cv = Math.sin(a);
    out[s * 2] = Math.sign(cu) * Math.pow(Math.abs(cu), exp) * ru;
    out[s * 2 + 1] = Math.sign(cv) * Math.pow(Math.abs(cv), exp) * rv;
  }
  return out;
}

/** Rings stacked along Y: torsos, limbs, stalks. */
export function loftY(B, rings, opts = {}) {
  const { sides = 12, exp = 0.7, origin = null, color, slot = 0, weights, capStart = true, capEnd = true } = opts;
  const buf = new Array(sides * 2);
  const grid = [];
  for (const r of rings) {
    superRing(sides, r.rx, r.rz ?? r.rx, r.exp ?? exp, buf);
    const row = [];
    for (let s = 0; s < sides; s++) {
      const p = new THREE.Vector3(buf[s * 2] + (r.cx ?? 0), r.y, buf[s * 2 + 1] + (r.cz ?? 0));
      if (origin) p.add(origin);
      row.push(p);
    }
    grid.push(row);
  }
  return emitGrid(B, grid, { color, slot, weights, wrap: true, capStart, capEnd });
}

/** Rings stacked along Z: heads, snouts, muzzles. */
export function loftZ(B, rings, opts = {}) {
  const { sides = 12, exp = 0.68, origin = null, color, slot = 0, weights, capStart = true, capEnd = true } = opts;
  const buf = new Array(sides * 2);
  const grid = [];
  for (const r of rings) {
    const top = r.top ?? r.ry ?? r.hw;
    const bot = r.bot ?? -(r.ry ?? r.hw);
    superRing(sides, r.hw, 1, r.exp ?? exp, buf);
    const row = [];
    for (let s = 0; s < sides; s++) {
      const v = buf[s * 2 + 1];
      const y = (v >= 0 ? top : -bot) * v + (r.cy ?? 0);
      const p = new THREE.Vector3(buf[s * 2] + (r.cx ?? 0), y, r.z);
      if (origin) p.add(origin);
      row.push(p);
    }
    grid.push(row);
  }
  return emitGrid(B, grid, { color, slot, weights, wrap: true, capStart, capEnd });
}

/** Hard-edged box, optionally rotated. Used for armour, helmets, crates. */
export function boxFlat(B, opts) {
  const { center, size, rot = null, color, slot = 0, weights, taper = 1, shear = 0 } = opts;
  const h = [size[0] / 2, size[1] / 2, size[2] / 2];
  const q = rot ? (rot.isQuaternion ? rot : new THREE.Quaternion().setFromEuler(rot)) : null;
  const corners = [];
  for (let i = 0; i < 8; i++) {
    const sx = i & 1 ? 1 : -1;
    const sy = i & 2 ? 1 : -1;
    const sz = i & 4 ? 1 : -1;
    const k = sy > 0 ? taper : 1;
    const p = new THREE.Vector3(sx * h[0] * k, sy * h[1], sz * h[2] * k);
    p.z += sy * shear;
    if (q) p.applyQuaternion(q);
    p.add(center);
    corners.push(p);
  }
  const C = (i) => corners[i];
  const w = typeof weights === 'function' ? weights(center) : weights;
  const col = typeof color === 'function' ? color(center) : color;
  // -Y, +Y, -Z, +Z, -X, +X
  B.quadFlat(C(0), C(4), C(5), C(1), col, w, slot);
  B.quadFlat(C(2), C(3), C(7), C(6), col, w, slot);
  B.quadFlat(C(0), C(1), C(3), C(2), col, w, slot);
  B.quadFlat(C(4), C(6), C(7), C(5), col, w, slot);
  B.quadFlat(C(0), C(2), C(6), C(4), col, w, slot);
  B.quadFlat(C(1), C(5), C(7), C(3), col, w, slot);
  return corners;
}

/**
 * A flat plate: four corners, both faces, with a slight thickness so it still
 * catches a rim light. Ears, wing membranes, capes, fins.
 */
export function plate(B, opts) {
  const { corners, thickness = 0.012, color, slot = 0, weights, normal = null } = opts;
  const [a, b, c, d] = corners;
  const nrm = normal
    ? normal.clone().normalize()
    : new THREE.Vector3().crossVectors(_v0.subVectors(b, a), _v1.subVectors(d, a)).normalize();
  const off = nrm.clone().multiplyScalar(thickness * 0.5);
  const up = [a, b, c, d].map((p) => p.clone().add(off));
  const dn = [a, b, c, d].map((p) => p.clone().sub(off));
  const col = typeof color === 'function' ? color(a) : color;
  const w = (p) => (typeof weights === 'function' ? weights(p) : weights);
  B.quadFlat(up[0], up[1], up[2], up[3], col, w(a), slot);
  B.quadFlat(dn[3], dn[2], dn[1], dn[0], col, w(a), slot);
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    B.quadFlat(up[j], up[i], dn[i], dn[j], col, w(up[i]), slot);
  }
}

/** Cone / spike, from base centre to tip. */
export function spike(B, opts) {
  const { base, tip, radius, sides = 6, color, slot = 0, weights, bend = null } = opts;
  const dir = new THREE.Vector3().subVectors(tip, base);
  const len = dir.length();
  dir.normalize();
  let side = new THREE.Vector3().crossVectors(UP, dir);
  if (side.lengthSq() < 1e-6) side.set(1, 0, 0);
  side.normalize();
  const bi = new THREE.Vector3().crossVectors(dir, side).normalize();

  const RINGS = bend ? 5 : 2;
  const grid = [];
  for (let i = 0; i < RINGS; i++) {
    const t = i / (RINGS - 1);
    const r = radius * (1 - t) * (1 - t * 0.25);
    const centre = base.clone().addScaledVector(dir, len * t);
    if (bend) centre.addScaledVector(bend, t * t);
    const row = [];
    for (let s = 0; s < sides; s++) {
      const a = (s / sides) * Math.PI * 2;
      row.push(centre.clone().addScaledVector(side, Math.cos(a) * r).addScaledVector(bi, Math.sin(a) * r));
    }
    grid.push(row);
  }
  // Pinch the last ring into a point.
  const tipP = grid[RINGS - 1][0].clone();
  for (const p of grid[RINGS - 1]) tipP.copy(p);
  const last = base.clone().addScaledVector(dir, len);
  if (bend) last.add(bend);
  for (const p of grid[RINGS - 1]) p.copy(last);

  return emitGrid(B, grid, { color, slot, weights, wrap: true, capStart: true });
}

