/**
 * Enemy colour, derived from the biome without dissolving into it.
 *
 * Two competing needs. The cast has to belong to the place — a frostspire gnorc
 * cannot be the same green as a verdant one — but it also has to stay readable
 * as a threat, which means it must never take the ground's hue *or* value. So
 * each archetype keeps a fixed identity colour and is only rotated part of the
 * way toward a biome slot, then pushed away from the ground's luminance until
 * it separates. Archetypes are also spread across the hue wheel from each other
 * so a brute never reads as a gnorc at fifty metres.
 */
import * as THREE from 'three';
import { luminance } from './Rig.js';

const _hslA = { h: 0, s: 0, l: 0 };
const _hslB = { h: 0, s: 0, l: 0 };

function lerpHue(a, b, t) {
  let d = b - a;
  if (d > 0.5) d -= 1;
  if (d < -0.5) d += 1;
  return (a + d * t + 1) % 1;
}

/** Rotate `base` partway toward `target`'s hue/saturation, keeping its value. */
function toward(base, target, amount, satAmount = 0.6) {
  const a = new THREE.Color(base);
  const b = new THREE.Color(target);
  a.getHSL(_hslA);
  b.getHSL(_hslB);
  return new THREE.Color().setHSL(
    lerpHue(_hslA.h, _hslB.h, amount),
    THREE.MathUtils.clamp(THREE.MathUtils.lerp(_hslA.s, _hslB.s, amount * satAmount), 0.06, 0.95),
    _hslA.l
  );
}

/** Force at least `minDelta` of lightness separation from the ground. */
function separate(color, groundL, minDelta = 0.2, bias = 0) {
  color.getHSL(_hslA);
  let l = _hslA.l + bias;
  if (Math.abs(l - groundL) < minDelta) {
    l = groundL > 0.5 ? Math.min(groundL - minDelta, l) : Math.max(groundL + minDelta, l);
  }
  color.setHSL(_hslA.h, _hslA.s, THREE.MathUtils.clamp(l, 0.07, 0.92));
  return color;
}

function boost(color, dS = 0.1, dL = 0) {
  color.getHSL(_hslA);
  color.setHSL(
    _hslA.h,
    THREE.MathUtils.clamp(_hslA.s + dS, 0, 1),
    THREE.MathUtils.clamp(_hslA.l + dL, 0.05, 0.95)
  );
  return color;
}

/** Fixed archetype identities — the part of the look that never moves. */
const IDENTITY = {
  gnorc: { skin: 0x76a340, cloth: 0x8a4f2a, metal: 0x9aa0aa, glowA: 0xffd24a, glowB: 0xfff2cf },
  thief: { skin: 0xd8b184, cloth: 0xd6452c, metal: 0xf0cc55, glowA: 0xfff0b0, glowB: 0xf2c14a },
  brute: { skin: 0x9a5f44, cloth: 0x333a45, metal: 0x808c9c, glowA: 0xff9a3a, glowB: 0xff5a1e },
  flyer: { skin: 0x584579, cloth: 0xa03c62, metal: 0xe4dcc8, glowA: 0xff5252, glowB: 0xffd0d0 },
  turret: { skin: 0x8f9a5c, cloth: 0x4f5a3a, metal: 0x66707e, glowA: 0xffb03a, glowB: 0x9fe8ff },
};

/**
 * Which biome slot each archetype's material listens to. Keeping these
 * different is what makes the cast read as five species instead of five sizes.
 */
const SOURCE = {
  gnorc: { skin: 'foliage.canopyA', cloth: 'rock.base', metal: 'rock.accent', pull: 0.5 },
  thief: { skin: 'ground.sand', cloth: 'foliage.flowerB', metal: 'accent', pull: 0.4 },
  brute: { skin: 'ground.cliff', cloth: 'rock.base', metal: 'rock.accent', pull: 0.42 },
  flyer: { skin: 'sky.zenith', cloth: 'foliage.flowerA', metal: 'ground.peak', pull: 0.52 },
  turret: { skin: 'foliage.grass', cloth: 'foliage.canopyA', metal: 'rock.accent', pull: 0.45 },
};

function pick(biome, path) {
  const [a, b] = path.split('.');
  return b ? biome[a][b] : biome[a];
}

/**
 * @returns {{skin,cloth,metal,glowA,glowB,glowPowerA,glowPowerB,accent}}
 */
export function enemyPalette(biome, kind) {
  const id = IDENTITY[kind] || IDENTITY.gnorc;
  const src = SOURCE[kind] || SOURCE.gnorc;
  const groundL = luminance(biome.ground.mid);
  const dark = groundL < 0.36;

  const skin = separate(toward(id.skin, pick(biome, src.skin), src.pull), groundL, 0.22, dark ? 0.08 : -0.04);
  const cloth = separate(toward(id.cloth, pick(biome, src.cloth), src.pull * 0.8), groundL, 0.24, dark ? 0.1 : -0.08);
  const metal = separate(toward(id.metal, pick(biome, src.metal), src.pull * 0.5, 0.35), groundL, 0.18, dark ? 0.12 : -0.1);

  // The hue spread is the whole point: nudge each archetype apart if the biome
  // pulled two of them onto the same hue.
  boost(skin, kind === 'thief' ? 0.14 : 0.08);
  boost(cloth, 0.12);

  // Glow keeps the biome accent for the "look at me" beats, but each archetype
  // owns one so the player learns the tell.
  const accent = new THREE.Color(biome.accent);
  const glowA = new THREE.Color(id.glowA).lerp(accent, kind === 'flyer' || kind === 'turret' ? 0.45 : 0.22);
  const glowB = new THREE.Color(id.glowB).lerp(accent, kind === 'turret' ? 0.6 : 0.15);
  boost(glowA, 0.25, 0.06);
  boost(glowB, 0.2, 0.04);

  return {
    skin,
    cloth,
    metal,
    glowA,
    glowB,
    glowPowerA: kind === 'brute' ? 0.9 : 1.15,
    glowPowerB: kind === 'turret' ? 0.7 : 0.85,
    accent,
  };
}

