import * as THREE from 'three';
import { buildGnorc } from '../../../../src/actors/enemies/Gnorc.js';
import { Rig, SLOT } from '../../../../src/actors/enemies/Rig.js';

const BONE_NAMES = [
  'root',
  'hips',
  'belly',
  'chest',
  'neck',
  'head',
  'jaw',
  'armL',
  'foreL',
  'handL',
  'armR',
  'foreR',
  'handR',
  'thighL',
  'shinL',
  'footL',
  'thighR',
  'shinR',
  'footR',
  'club',
];

const CLIP_CONTRACT = {
  idle: { duration: 3.0, loop: THREE.LoopRepeat, keyframes: 5 },
  walk: { duration: 1.0, loop: THREE.LoopRepeat, keyframes: 9 },
  run: { duration: 0.62, loop: THREE.LoopRepeat, keyframes: 9 },
  alert: { duration: 0.85, loop: THREE.LoopOnce, keyframes: 4 },
  attack: { duration: 0.78, loop: THREE.LoopOnce, keyframes: 5 },
  hurt: { duration: 0.42, loop: THREE.LoopOnce, keyframes: 3 },
  die: { duration: 0.95, loop: THREE.LoopOnce, keyframes: 4 },
  taunt: { duration: 1.3, loop: THREE.LoopOnce, keyframes: 5 },
};

const ATTRIBUTE_LAYOUT = {
  position: 3,
  normal: 3,
  color: 3,
  aSlot: 1,
  skinIndex: 4,
  skinWeight: 4,
};

function arrayOf(geometry, name) {
  return geometry.getAttribute(name).array;
}

function findTrack(clip, trackName) {
  const track = clip.tracks.find((t) => t.name === trackName);
  expect(track).toBeDefined();
  return track;
}

function valuesAtTime(track, time) {
  const size = track.getValueSize();
  let best = 0;
  for (let i = 1; i < track.times.length; i++) {
    if (Math.abs(track.times[i] - time) < Math.abs(track.times[best] - time)) best = i;
  }
  return Array.from({ length: size }, (_, i) => track.values[best * size + i]);
}

function expectArrayCloseTo(actual, expected, digits = 5) {
  expect(actual).toHaveLength(expected.length);
  actual.forEach((value, i) => expect(value).toBeCloseTo(expected[i], digits));
}

function dominantBone(geometry, vertex) {
  const skinIndex = arrayOf(geometry, 'skinIndex');
  const skinWeight = arrayOf(geometry, 'skinWeight');
  const base = vertex * 4;
  let best = 0;
  for (let i = 1; i < 4; i++) {
    if (skinWeight[base + i] > skinWeight[base + best]) best = i;
  }
  return skinIndex[base + best];
}

function verticesDominatedBy(geometry, boneIndex) {
  const position = arrayOf(geometry, 'position');
  const count = geometry.getAttribute('position').count;
  const out = [];
  for (let v = 0; v < count; v++) {
    if (dominantBone(geometry, v) !== boneIndex) continue;
    const p = v * 3;
    out.push({ x: position[p], y: position[p + 1], z: position[p + 2] });
  }
  return out;
}

describe('buildGnorc', () => {
  let result;

  beforeEach(() => {
    result = buildGnorc();
  });

  it('returns the complete Gnorc asset bundle', () => {
    expect(result).toEqual(
      expect.objectContaining({
        rig: expect.any(Object),
        geometry: expect.any(THREE.BufferGeometry),
        clips: expect.any(Object),
        meta: expect.any(Object),
      })
    );
    expect(result.rig).toBeInstanceOf(Rig);
    expect(Object.keys(result).sort()).toEqual(['clips', 'geometry', 'meta', 'rig']);
  });

  it('exposes the gameplay metadata used by the enemy system', () => {
    expect(result.meta).toEqual({
      kind: 'gnorc',
      height: 1.5,
      radius: 0.55,
      hitHeight: 0.8,
      eyeHeight: 1.2,
      groundOffset: 0,
      scale: 1,
    });
  });

  it('builds a non-empty indexed geometry with a consistent skinning layout', () => {
    const { geometry } = result;
    const vertexCount = geometry.getAttribute('position').count;

    expect(vertexCount).toBeGreaterThan(0);
    for (const [name, itemSize] of Object.entries(ATTRIBUTE_LAYOUT)) {
      const attribute = geometry.getAttribute(name);
      expect(attribute).toBeDefined();
      expect(attribute.itemSize).toBe(itemSize);
      expect(attribute.count).toBe(vertexCount);
    }

    expect(geometry.index).not.toBeNull();
    const indices = geometry.index.array;
    expect(indices.length).toBeGreaterThan(0);
    expect(indices.length % 3).toBe(0);
    for (let i = 0; i < indices.length; i++) {
      expect(Number.isInteger(indices[i])).toBe(true);
      expect(indices[i]).toBeGreaterThanOrEqual(0);
      expect(indices[i]).toBeLessThan(vertexCount);
    }
  });

  it('stands on the ground and fills the intended short, wide silhouette', () => {
    const { geometry } = result;
    geometry.computeBoundingBox();
    const { min, max } = geometry.boundingBox;

    // The root sits between the feet, exactly on the ground plane.
    expect(min.y).toBeGreaterThanOrEqual(-1e-5);
    expect(min.y).toBeCloseTo(0, 5);

    // The horn is the tallest point, below the nominal 1.5m capsule height.
    expect(max.y).toBeGreaterThan(1.35);
    expect(max.y).toBeLessThanOrEqual(1.5);

    // Arms and the club push the silhouette out well past the body half-width.
    expect(min.x).toBeLessThan(-0.4);
    expect(max.x).toBeGreaterThan(0.4);
    expect(min.z).toBeLessThan(-0.2);
    expect(max.z).toBeGreaterThan(0.3);
  });

  it('computes a finite bounding sphere that encloses every vertex', () => {
    const { geometry } = result;
    const sphere = geometry.boundingSphere;
    const position = arrayOf(geometry, 'position');

    expect(sphere).not.toBeNull();
    expect(Number.isFinite(sphere.center.x)).toBe(true);
    expect(Number.isFinite(sphere.center.y)).toBe(true);
    expect(Number.isFinite(sphere.center.z)).toBe(true);
    expect(Number.isFinite(sphere.radius)).toBe(true);
    expect(sphere.radius).toBeGreaterThan(0);

    let maxDistance = 0;
    for (let i = 0; i < position.length; i += 3) {
      const dx = position[i] - sphere.center.x;
      const dy = position[i + 1] - sphere.center.y;
      const dz = position[i + 2] - sphere.center.z;
      maxDistance = Math.max(maxDistance, Math.hypot(dx, dy, dz));
    }
    expect(maxDistance).toBeLessThanOrEqual(sphere.radius + 1e-4);
  });

  it('emits finite positions and unit-length face normals', () => {
    const { geometry } = result;
    const position = arrayOf(geometry, 'position');
    const normal = arrayOf(geometry, 'normal');

    let maxNormalError = 0;
    for (let i = 0; i < position.length; i++) {
      expect(Number.isFinite(position[i])).toBe(true);
      expect(Number.isFinite(normal[i])).toBe(true);
    }
    for (let i = 0; i < normal.length; i += 3) {
      const length = Math.hypot(normal[i], normal[i + 1], normal[i + 2]);
      maxNormalError = Math.max(maxNormalError, Math.abs(length - 1));
    }
    expect(maxNormalError).toBeLessThan(1e-5);
  });

  it('normalizes every vertex to at most four valid rig bones', () => {
    const { geometry, rig } = result;
    const skinIndex = arrayOf(geometry, 'skinIndex');
    const skinWeight = arrayOf(geometry, 'skinWeight');
    const vertexCount = geometry.getAttribute('position').count;
    const usedBones = new Set();

    let maxWeightError = 0;
    for (let v = 0; v < vertexCount; v++) {
      const base = v * 4;
      let sum = 0;
      for (let i = 0; i < 4; i++) {
        const weight = skinWeight[base + i];
        const bone = skinIndex[base + i];
        expect(Number.isFinite(weight)).toBe(true);
        expect(weight).toBeGreaterThanOrEqual(0);
        expect(Number.isInteger(bone)).toBe(true);
        expect(bone).toBeGreaterThanOrEqual(0);
        expect(bone).toBeLessThan(rig.names.length);
        sum += weight;
        usedBones.add(bone);
      }
      maxWeightError = Math.max(maxWeightError, Math.abs(sum - 1));
    }
    expect(maxWeightError).toBeLessThan(1e-5);

    // Every declared bone drives part of the skin, including the club.
    expect([...usedBones].sort((a, b) => a - b)).toEqual(
      Array.from({ length: rig.names.length }, (_, i) => i)
    );
  });

  it('tags the geometry with all palette slots used by the enemy renderer', () => {
    const { geometry } = result;
    const slots = [...new Set(arrayOf(geometry, 'aSlot'))];

    expect(slots).toContain(SLOT.none);
    expect(slots).toContain(SLOT.skin);
    expect(slots).toContain(SLOT.cloth);
    expect(slots).toContain(SLOT.metal);
    expect(slots).toContain(SLOT.glowA);
    for (const slot of slots) {
      expect(Number.isInteger(slot)).toBe(true);
      expect(Object.values(SLOT)).toContain(slot);
    }

    // The body is predominantly skin; the other slots only provide accents.
    const slotCounts = {};
    for (const slot of arrayOf(geometry, 'aSlot')) slotCounts[slot] = (slotCounts[slot] || 0) + 1;
    expect(slotCounts[SLOT.skin]).toBeGreaterThan(geometry.getAttribute('aSlot').count / 2);
  });

  it('stores shaded vertex colours in range with visible value variation', () => {
    const { geometry } = result;
    const color = arrayOf(geometry, 'color');
    let min = Infinity;
    let max = -Infinity;

    for (let i = 0; i < color.length; i++) {
      expect(Number.isFinite(color[i])).toBe(true);
      expect(color[i]).toBeGreaterThanOrEqual(0);
      expect(color[i]).toBeLessThanOrEqual(1);
      min = Math.min(min, color[i]);
      max = Math.max(max, color[i]);
    }
    expect(max - min).toBeGreaterThan(0.2);
  });

  it('binds the head, jaw, feet, hands and club to their expected bones', () => {
    const { geometry, rig } = result;

