    expect(head.length).toBeGreaterThan(0);
    expect(head.every((p) => p.y >= 1.0 && p.y <= 1.5)).toBe(true);
    expect(head.some((p) => p.x > 0.2)).toBe(true);
    expect(head.some((p) => p.x < -0.2)).toBe(true);

    const jaw = verticesDominatedBy(geometry, rig.boneIndex.jaw);
    expect(jaw.length).toBeGreaterThan(0);
    expect(jaw.every((p) => p.y >= 1.0 && p.y <= 1.3)).toBe(true);
    expect(Math.max(...jaw.map((p) => p.z))).toBeGreaterThan(0.2);

    const footL = verticesDominatedBy(geometry, rig.boneIndex.footL);
    const footR = verticesDominatedBy(geometry, rig.boneIndex.footR);
    expect(footL.length).toBeGreaterThan(0);
    expect(footR.length).toBeGreaterThan(0);
    expect(footL.every((p) => p.x > 0 && p.y <= 0.15)).toBe(true);
    expect(footR.every((p) => p.x < 0 && p.y <= 0.15)).toBe(true);

    const handL = verticesDominatedBy(geometry, rig.boneIndex.handL);
    const handR = verticesDominatedBy(geometry, rig.boneIndex.handR);
    expect(handL.length).toBeGreaterThan(0);
    expect(handR.length).toBeGreaterThan(0);
    expect(handL.every((p) => p.x > 0.4)).toBe(true);
    expect(handR.every((p) => p.x < -0.4)).toBe(true);

    const club = verticesDominatedBy(geometry, rig.boneIndex.club);
    expect(club.length).toBeGreaterThan(0);
    expect(club.every((p) => p.x < -0.4)).toBe(true);
    expect(Math.min(...club.map((p) => p.y))).toBeLessThan(0.55);
    expect(Math.max(...club.map((p) => p.y))).toBeGreaterThan(1.0);
  });

  it('builds the expected bone hierarchy and bind pose', () => {
    const { rig } = result;

    expect(rig.names).toEqual(BONE_NAMES);
    BONE_NAMES.forEach((name, index) => expect(rig.boneIndex[name]).toBe(index));

    expect(rig.p('root').toArray()).toEqual([0, 0, 0]);
    expect(rig.p('hips').y).toBeCloseTo(0.5, 5);
    expect(rig.p('head').y).toBeCloseTo(1.13, 5);
    expect(rig.p('club').toArray()).toEqual(
      expect.arrayContaining([expect.closeTo(-0.61, 5), expect.closeTo(0.62, 5), expect.closeTo(0.1, 5)])
    );

    const instance = rig.instantiate();
    expect(instance.root.name).toBe('root');
    expect(instance.bones).toHaveLength(BONE_NAMES.length);
    expect(instance.bones.map((bone) => bone.name)).toEqual(BONE_NAMES);
    expect(instance.map.jaw.parent.name).toBe('head');
    expect(instance.map.club.parent.name).toBe('handR');
    expect(instance.map.footL.parent.name).toBe('shinL');
    expect(instance.map.footR.parent.name).toBe('shinR');
    expect(instance.map.head.parent.name).toBe('neck');
    expect(instance.map.hips.parent.name).toBe('root');
    instance.skeleton.bones.forEach((bone, i) => expect(bone).toBe(instance.bones[i]));

    // Each instantiate call must hand out independent bones.
    const second = rig.instantiate();
    expect(second.root).not.toBe(instance.root);
    expect(second.map.head).not.toBe(instance.map.head);
    expect(second.map.club).not.toBe(instance.map.club);
