  skinWeight: 4,
};

function arrayOf(geometry, name) {
  return geometry.getAttribute(name).array;
}

function findTrack(clip, trackName) {
  const track = clip.tracks.find((t) => t.name === trackName);
  expect(track).toBeDefined();
  return track;
}

function valuesAtTime(track, time) {
  const size = track.getValueSize();
  let best = 0;
  for (let i = 1; i < track.times.length; i++) {
    if (Math.abs(track.times[i] - time) < Math.abs(track.times[best] - time)) best = i;
  }
  return Array.from({ length: size }, (_, i) => track.values[best * size + i]);
}

function expectArrayCloseTo(actual, expected, digits = 5) {
  expect(actual).toHaveLength(expected.length);
  actual.forEach((value, i) => expect(value).toBeCloseTo(expected[i], digits));
}

function dominantBone(geometry, vertex) {
  const skinIndex = arrayOf(geometry, 'skinIndex');
  const skinWeight = arrayOf(geometry, 'skinWeight');
  const base = vertex * 4;
  let best = 0;
  for (let i = 1; i < 4; i++) {
    if (skinWeight[base + i] > skinWeight[base + best]) best = i;
  }
  return skinIndex[base + best];
}

function verticesDominatedBy(geometry, boneIndex) {
  const position = arrayOf(geometry, 'position');
  const count = geometry.getAttribute('position').count;
  const out = [];
  for (let v = 0; v < count; v++) {
    if (dominantBone(geometry, v) !== boneIndex) continue;
    const p = v * 3;
    out.push({ x: position[p], y: position[p + 1], z: position[p + 2] });
  }
  return out;
}

describe('buildGnorc', () => {
  let result;

  beforeEach(() => {
    result = buildGnorc();
  });

  it('returns the complete Gnorc asset bundle', () => {
    expect(result).toEqual(
      expect.objectContaining({
        rig: expect.any(Object),
        geometry: expect.any(THREE.BufferGeometry),
        clips: expect.any(Object),
        meta: expect.any(Object),
      })
    );
    expect(result.rig).toBeInstanceOf(Rig);
    expect(Object.keys(result).sort()).toEqual(['clips', 'geometry', 'meta', 'rig']);
  });

  it('exposes the gameplay metadata used by the enemy system', () => {
    expect(result.meta).toEqual({
      kind: 'gnorc',
      height: 1.5,
      radius: 0.55,
      hitHeight: 0.8,
      eyeHeight: 1.2,
      groundOffset: 0,
      scale: 1,
    });
  });

  it('builds a non-empty indexed geometry with a consistent skinning layout', () => {
    const { geometry } = result;
    const vertexCount = geometry.getAttribute('position').count;

    expect(vertexCount).toBeGreaterThan(0);
    for (const [name, itemSize] of Object.entries(ATTRIBUTE_LAYOUT)) {
      const attribute = geometry.getAttribute(name);
      expect(attribute).toBeDefined();
      expect(attribute.itemSize).toBe(itemSize);
      expect(attribute.count).toBe(vertexCount);
    }

    expect(geometry.index).not.toBeNull();
    const indices = geometry.index.array;
    expect(indices.length).toBeGreaterThan(0);
    expect(indices.length % 3).toBe(0);
    for (let i = 0; i < indices.length; i++) {
      expect(Number.isInteger(indices[i])).toBe(true);
      expect(indices[i]).toBeGreaterThanOrEqual(0);
      expect(indices[i]).toBeLessThan(vertexCount);
    }
  });

  it('stands on the ground and fills the intended short, wide silhouette', () => {
    const { geometry } = result;
    geometry.computeBoundingBox();
    const { min, max } = geometry.boundingBox;

    // The root sits between the feet, exactly on the ground plane.
    expect(min.y).toBeGreaterThanOrEqual(-1e-5);
    expect(min.y).toBeCloseTo(0, 5);

    // The horn is the tallest point, below the nominal 1.5m capsule height.
    expect(max.y).toBeGreaterThan(1.35);
    expect(max.y).toBeLessThanOrEqual(1.5);

    // Arms and the club push the silhouette out well past the body half-width.
    expect(min.x).toBeLessThan(-0.4);
    expect(max.x).toBeGreaterThan(0.4);
    expect(min.z).toBeLessThan(-0.2);
    expect(max.z).toBeGreaterThan(0.3);
  });

  it('computes a finite bounding sphere that encloses every vertex', () => {
    const { geometry } = result;
    const sphere = geometry.boundingSphere;
    const position = arrayOf(geometry, 'position');

    expect(sphere).not.toBeNull();
    expect(Number.isFinite(sphere.center.x)).toBe(true);
    expect(Number.isFinite(sphere.center.y)).toBe(true);
    expect(Number.isFinite(sphere.center.z)).toBe(true);
    expect(Number.isFinite(sphere.radius)).toBe(true);
    expect(sphere.radius).toBeGreaterThan(0);

    let maxDistance = 0;
    for (let i = 0; i < position.length; i += 3) {
      const dx = position[i] - sphere.center.x;
      const dy = position[i + 1] - sphere.center.y;
      const dz = position[i + 2] - sphere.center.z;
      maxDistance = Math.max(maxDistance, Math.hypot(dx, dy, dz));
    }
    expect(maxDistance).toBeLessThanOrEqual(sphere.radius + 1e-4);
  });

  it('emits finite positions and unit-length face normals', () => {
    const { geometry } = result;
    const position = arrayOf(geometry, 'position');
    const normal = arrayOf(geometry, 'normal');

    let maxNormalError = 0;
    for (let i = 0; i < position.length; i++) {
      expect(Number.isFinite(position[i])).toBe(true);
      expect(Number.isFinite(normal[i])).toBe(true);
    }
    for (let i = 0; i < normal.length; i += 3) {
      const length = Math.hypot(normal[i], normal[i + 1], normal[i + 2]);
      maxNormalError = Math.max(maxNormalError, Math.abs(length - 1));
    }
    expect(maxNormalError).toBeLessThan(1e-5);
  });

  it('normalizes every vertex to at most four valid rig bones', () => {
    const { geometry, rig } = result;
    const skinIndex = arrayOf(geometry, 'skinIndex');
    const skinWeight = arrayOf(geometry, 'skinWeight');
    const vertexCount = geometry.getAttribute('position').count;
    const usedBones = new Set();

    let maxWeightError = 0;
    for (let v = 0; v < vertexCount; v++) {
      const base = v * 4;
      let sum = 0;
      for (let i = 0; i < 4; i++) {
        const weight = skinWeight[base + i];
        const bone = skinIndex[base + i];
        expect(Number.isFinite(weight)).toBe(true);
        expect(weight).toBeGreaterThanOrEqual(0);
        expect(Number.isInteger(bone)).toBe(true);
        expect(bone).toBeGreaterThanOrEqual(0);
        expect(bone).toBeLessThan(rig.names.length);
        sum += weight;
        usedBones.add(bone);
      }
      maxWeightError = Math.max(maxWeightError, Math.abs(sum - 1));
    }
    expect(maxWeightError).toBeLessThan(1e-5);

    // Every declared bone drives part of the skin, including the club.
    expect([...usedBones].sort((a, b) => a - b)).toEqual(
      Array.from({ length: rig.names.length }, (_, i) => i)
    );
  });

  it('tags the geometry with all palette slots used by the enemy renderer', () => {
    const { geometry } = result;
    const slots = [...new Set(arrayOf(geometry, 'aSlot'))];

    expect(slots).toContain(SLOT.none);
    expect(slots).toContain(SLOT.skin);
    expect(slots).toContain(SLOT.cloth);
    expect(slots).toContain(SLOT.metal);
    expect(slots).toContain(SLOT.glowA);
    for (const slot of slots) {
      expect(Number.isInteger(slot)).toBe(true);
      expect(Object.values(SLOT)).toContain(slot);
    }

    // The body is predominantly skin; the other slots only provide accents.
    const slotCounts = {};
    for (const slot of arrayOf(geometry, 'aSlot')) slotCounts[slot] = (slotCounts[slot] || 0) + 1;
    expect(slotCounts[SLOT.skin]).toBeGreaterThan(geometry.getAttribute('aSlot').count / 2);
  });

  it('stores shaded vertex colours in range with visible value variation', () => {
    const { geometry } = result;
    const color = arrayOf(geometry, 'color');
    let min = Infinity;
    let max = -Infinity;

    for (let i = 0; i < color.length; i++) {
      expect(Number.isFinite(color[i])).toBe(true);
      expect(color[i]).toBeGreaterThanOrEqual(0);
      expect(color[i]).toBeLessThanOrEqual(1);
      min = Math.min(min, color[i]);
      max = Math.max(max, color[i]);
    }
    expect(max - min).toBeGreaterThan(0.2);
  });

  it('binds the head, jaw, feet, hands and club to their expected bones', () => {
    const { geometry, rig } = result;

    const head = verticesDominatedBy(geometry, rig.boneIndex.head);
    expect(head.length).toBeGreaterThan(0);
    expect(head.every((p) => p.y >= 1.0 && p.y <= 1.5)).toBe(true);
    expect(head.some((p) => p.x > 0.2)).toBe(true);
    expect(head.some((p) => p.x < -0.2)).toBe(true);

    const jaw = verticesDominatedBy(geometry, rig.boneIndex.jaw);
    expect(jaw.length).toBeGreaterThan(0);
    expect(jaw.every((p) => p.y >= 1.0 && p.y <= 1.3)).toBe(true);
    expect(Math.max(...jaw.map((p) => p.z))).toBeGreaterThan(0.2);

    const footL = verticesDominatedBy(geometry, rig.boneIndex.footL);
    const footR = verticesDominatedBy(geometry, rig.boneIndex.footR);
    expect(footL.length).toBeGreaterThan(0);
    expect(footR.length).toBeGreaterThan(0);
    expect(footL.every((p) => p.x > 0 && p.y <= 0.15)).toBe(true);
    expect(footR.every((p) => p.x < 0 && p.y <= 0.15)).toBe(true);

    const handL = verticesDominatedBy(geometry, rig.boneIndex.handL);
    const handR = verticesDominatedBy(geometry, rig.boneIndex.handR);
    expect(handL.length).toBeGreaterThan(0);
    expect(handR.length).toBeGreaterThan(0);
    expect(handL.every((p) => p.x > 0.4)).toBe(true);
    expect(handR.every((p) => p.x < -0.4)).toBe(true);

    const club = verticesDominatedBy(geometry, rig.boneIndex.club);
    expect(club.length).toBeGreaterThan(0);
    expect(club.every((p) => p.x < -0.4)).toBe(true);
    expect(Math.min(...club.map((p) => p.y))).toBeLessThan(0.55);
    expect(Math.max(...club.map((p) => p.y))).toBeGreaterThan(1.0);
  });

  it('builds the expected bone hierarchy and bind pose', () => {
    const { rig } = result;

    expect(rig.names).toEqual(BONE_NAMES);
    BONE_NAMES.forEach((name, index) => expect(rig.boneIndex[name]).toBe(index));

    expect(rig.p('root').toArray()).toEqual([0, 0, 0]);
    expect(rig.p('hips').y).toBeCloseTo(0.5, 5);
    expect(rig.p('head').y).toBeCloseTo(1.13, 5);
    expect(rig.p('club').toArray()).toEqual(
      expect.arrayContaining([expect.closeTo(-0.61, 5), expect.closeTo(0.62, 5), expect.closeTo(0.1, 5)])
    );

    const instance = rig.instantiate();
    expect(instance.root.name).toBe('root');
    expect(instance.bones).toHaveLength(BONE_NAMES.length);
    expect(instance.bones.map((bone) => bone.name)).toEqual(BONE_NAMES);
    expect(instance.map.jaw.parent.name).toBe('head');
    expect(instance.map.club.parent.name).toBe('handR');
    expect(instance.map.footL.parent.name).toBe('shinL');
    expect(instance.map.footR.parent.name).toBe('shinR');
    expect(instance.map.head.parent.name).toBe('neck');
    expect(instance.map.hips.parent.name).toBe('root');
    instance.skeleton.bones.forEach((bone, i) => expect(bone).toBe(instance.bones[i]));

    // Each instantiate call must hand out independent bones.
    const second = rig.instantiate();
    expect(second.root).not.toBe(instance.root);
    expect(second.map.head).not.toBe(instance.map.head);
    expect(second.map.club).not.toBe(instance.map.club);
  });

  it('authors all eight clips with the expected durations and loop modes', () => {
    const { clips } = result;

    expect(Object.keys(clips).sort()).toEqual(Object.keys(CLIP_CONTRACT).sort());
    for (const [name, spec] of Object.entries(CLIP_CONTRACT)) {
      const clip = clips[name];
      expect(clip).toBeInstanceOf(THREE.AnimationClip);
      expect(clip.name).toBe(name);
      expect(clip.duration).toBeCloseTo(spec.duration, 5);
      expect(clip.tracks.length).toBeGreaterThan(0);
      expect(clip.userData.loop).toBe(spec.loop);

      const distinctTimes = new Set();
      for (const track of clip.tracks) distinctTimes.add(track.times[0]);
      expect(distinctTimes.size).toBe(1);
      expect([...distinctTimes][0]).toBeCloseTo(0, 5);
    }
  });

  it('keeps every clip track on a real bone and inside the clip timeline', () => {
    const { clips, rig } = result;

    for (const [name, clip] of Object.entries(clips)) {
      const allTimes = new Set();
      for (const track of clip.tracks) {
        const [bone, property] = track.name.split('.');
        expect(rig.names).toContain(bone);
        expect(['quaternion', 'position', 'scale']).toContain(property);
        expect(track.times.length).toBeGreaterThan(1);
        expect(track.values.length).toBe(track.times.length * track.getValueSize());

        expect(track.times[0]).toBeCloseTo(0, 5);
        expect(track.times[track.times.length - 1]).toBeCloseTo(CLIP_CONTRACT[name].duration, 5);
        for (let i = 1; i < track.times.length; i++) {
          expect(track.times[i]).toBeGreaterThanOrEqual(track.times[i - 1]);
        }
        for (let i = 0; i < track.values.length; i++) {
          expect(Number.isFinite(track.values[i])).toBe(true);
        }
        for (const time of track.times) allTimes.add(time);
      }
      expect(allTimes.size).toBe(CLIP_CONTRACT[name].keyframes);
    }
  });

  it('closes the locomotion loops seamlessly', () => {
    const { clips } = result;

    for (const name of ['idle', 'walk', 'run']) {
      for (const track of clips[name].tracks) {
        const size = track.getValueSize();
        for (let i = 0; i < size; i++) {
          const first = track.values[i];
          const last = track.values[track.values.length - size + i];
          expect(last).toBeCloseTo(first, 5);
        }
      }
    }
  });

  it('animates vertical root motion for idle sway and reaction poses', () => {
    const { clips } = result;

    const idleRoot = findTrack(clips.idle, 'root.position');
    const idleY = [];
    for (let i = 1; i < idleRoot.values.length; i += 3) idleY.push(idleRoot.values[i]);
    expect(Math.min(...idleY)).toBeCloseTo(0, 5);
    expect(Math.max(...idleY)).toBeCloseTo(0.012, 5);

    const alertRoot = findTrack(clips.alert, 'root.position');
    expectArrayCloseTo(valuesAtTime(alertRoot, 0.11), [0, 0.16, 0]);
    expectArrayCloseTo(valuesAtTime(alertRoot, 0.32), [0, -0.1, 0]);

    const hurtRoot = findTrack(clips.hurt, 'root.position');
    expectArrayCloseTo(valuesAtTime(hurtRoot, 0.1), [0, 0.05, 0]);

    const dieRoot = findTrack(clips.die, 'root.position');
    expectArrayCloseTo(valuesAtTime(dieRoot, 0.14), [0, 0.2, 0]);
    expectArrayCloseTo(valuesAtTime(dieRoot, 0.95), [0, -0.06, 0]);
  });

  it('adds squash-and-stretch keys to the reaction clips', () => {
    const { clips } = result;

    expectArrayCloseTo(valuesAtTime(findTrack(clips.alert, 'belly.scale'), 0.11), [0.9, 1.16, 0.9]);
    expectArrayCloseTo(valuesAtTime(findTrack(clips.alert, 'belly.scale'), 0.32), [1.08, 0.94, 1.08]);

    expectArrayCloseTo(valuesAtTime(findTrack(clips.hurt, 'belly.scale'), 0.1), [1.14, 0.86, 1.14]);

    expectArrayCloseTo(valuesAtTime(findTrack(clips.taunt, 'belly.scale'), 0.3), [1.12, 0.94, 1.12]);
    expectArrayCloseTo(valuesAtTime(findTrack(clips.taunt, 'belly.scale'), 0.52), [0.94, 1.08, 0.94]);

    // The one-shot clips start and finish in neutral squash.
    for (const name of ['alert', 'hurt', 'taunt']) {
      const track = findTrack(clips[name], 'belly.scale');
      expectArrayCloseTo(valuesAtTime(track, 0), [1, 1, 1]);
      expectArrayCloseTo(valuesAtTime(track, CLIP_CONTRACT[name].duration), [1, 1, 1]);
    }
  });

  it('swings the club through a full attack arc', () => {
    const { clips } = result;
    const club = findTrack(clips.attack, 'club.quaternion');
    const size = club.getValueSize();

    const first = Array.from({ length: size }, (_, i) => club.values[i]);
    const last = Array.from({ length: size }, (_, i) => club.values[club.values.length - size + i]);
    expectArrayCloseTo(last, first);

    let maxDelta = 0;
    for (let i = 0; i < size; i++) {
      maxDelta = Math.max(maxDelta, Math.abs(club.values[size + i] - first[i]));
    }
    expect(maxDelta).toBeGreaterThan(0.4);
  });

  it('is deterministic while returning fresh mutable assets per build', () => {
    const first = buildGnorc();
    const second = buildGnorc();

    expect(second).not.toBe(first);
    expect(second.rig).not.toBe(first.rig);
    expect(second.geometry).not.toBe(first.geometry);
    expect(second.clips).not.toBe(first.clips);

    for (const name of Object.keys(ATTRIBUTE_LAYOUT)) {
      expect(Array.from(arrayOf(second.geometry, name))).toEqual(
        Array.from(arrayOf(first.geometry, name))
      );
    }
    expect(Array.from(second.geometry.index.array)).toEqual(
      Array.from(first.geometry.index.array)
    );

    for (const name of Object.keys(CLIP_CONTRACT)) {
      expect(second.clips[name].toJSON()).toEqual(first.clips[name].toJSON());
    }

    // Geometry buffers are not shared between builds.
    first.geometry.getAttribute('position').array[0] += 1;
    expect(second.geometry.getAttribute('position').array[0]).not.toBe(
      first.geometry.getAttribute('position').array[0]
    );
  });
});
