--- Rng ---
/**
 * Deterministic random + noise. Everything procedural in the game must draw from
 * an Rng forked off the run seed so a seed reproduces a run exactly.
 */
import { createNoise2D, createNoise3D } from 'simplex-noise';

export function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** FNV-1a — turns a string tag into a 32-bit seed. */
export function hashString(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export class Rng {
  constructor(seed = Date.now()) {
    this.seed = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
    this._next = mulberry32(this.seed);
  }

  next() {
    return this._next();
  }

  /** Uniform in [min, max). */
  range(min, max) {
    return min + this._next() * (max - min);
  }

  /** Integer in [min, max]. */
  int(min, max) {
    return Math.floor(min + this._next() * (max - min + 1));
  }

  bool(p = 0.5) {
    return this._next() < p;
  }

  sign() {
    return this._next() < 0.5 ? -1 : 1;
  }

  pick(arr) {
    return arr[Math.floor(this._next() * arr.length)];
  }

  /** Pick from [{weight, ...}] or from `items` using parallel `weights`. */
  weighted(items, weights) {
    const w = weights || items.map((i) => i.weight ?? 1);
    let total = 0;
    for (let i = 0; i < w.length; i++) total += w[i];
    let r = this._next() * total;
    for (let i = 0; i < items.length; i++) {
      r -= w[i];
      if (r <= 0) return items[i];
    }
    return items[items.length - 1];
  }

  /** In-place Fisher-Yates. Returns the same array. */
  shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(this._next() * (i + 1));
      const t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
    return arr;
  }

  /** Box-Muller. */
  gauss(mean = 0, sd = 1) {
    let u = 0;
    let v = 0;
    while (u === 0) u = this._next();
    while (v === 0) v = this._next();
    return mean + sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  /** Uniform point in a unit disc, as [x, y]. */
  disc(radius = 1) {
    const r = radius * Math.sqrt(this._next());
    const a = this._next() * Math.PI * 2;
    return [Math.cos(a) * r, Math.sin(a) * r];
  }

  /**
   * Deterministic child generator. Same tag + same parent seed => same stream,
   * regardless of how much the parent has been consumed. Use this to keep
   * subsystems independent: adding a tree must not shift enemy placement.
   */
  fork(tag) {
    return new Rng((this.seed ^ hashString(String(tag))) >>> 0);
  }
}

/** simplex-noise bound to a deterministic stream. */
export function makeNoise2D(rng) {
  return createNoise2D(() => rng.next());
}

export function makeNoise3D(rng) {
  return createNoise3D(() => rng.next());
}

/** Fractal brownian motion over a 2D noise fn. Returns roughly [-1, 1]. */
export function fbm2(noise2, x, y, octaves = 4, lacunarity = 2.0, gain = 0.5) {
  let amp = 1;
  let freq = 1;
  let sum = 0;
  let norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += amp * noise2(x * freq, y * freq);
    norm += amp;
    amp *= gain;
    freq *= lacunarity;
  }
  return sum / norm;
}

/** Ridged fbm — sharp crests, good for rock and mountain silhouettes. */
export function ridged2(noise2, x, y, octaves = 4, lacunarity = 2.0, gain = 0.5) {
  let amp = 1;
  let freq = 1;
  let sum = 0;
  let norm = 0;
  for (let i = 0; i < octaves; i++) {
    const n = 1 - Math.abs(noise2(x * freq, y * freq));
    sum += amp * n * n;
    norm += amp;
    amp *= gain;
    freq *= lacunarity;
  }
  return (sum / norm) * 2 - 1;
}

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const smoothstep = (e0, e1, x) => {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
};
/** Frame-rate independent exponential approach. `rate` = fraction closed per second. */
export const damp = (a, b, rate, dt) => lerp(a, b, 1 - Math.exp(-rate * dt));

import * as THREE from 'three';
import { mulberry32 } from '../core/Rng.js';
import { BIOMES } from '../world/Biomes.js';
import { makeSpriteAtlas, TILE } from './Textures.js';
import { ParticlePool, MODE, makeEmitParams, resetEmitParams } from './ParticlePool.js';
import { Ambient } from './Ambient.js';

const TAU = Math.PI * 2;
const UP = new THREE.Vector3(0, 1, 0);

// Dragon fire ramp. Four stops, hot to dead.
const FIRE_HOT = new THREE.Color(0xfff4ce);
const FIRE_MID = new THREE.Color(0xffae33);
const FIRE_LOW = new THREE.Color(0xe0431a);
const FIRE_DEAD = new THREE.Color(0x611004);

// Reusable scratch. Nothing in this file allocates per frame or per emit.
const _v0 = new THREE.Vector3();
const _v1 = new THREE.Vector3();
const _dx = new THREE.Vector3();
const _dy = new THREE.Vector3();
const _dz = new THREE.Vector3();
const _c0 = new THREE.Color();
const _c1 = new THREE.Color();

const QUALITY_BUDGET = { low: 0.42, medium: 0.68, high: 1.0, ultra: 1.2 };

export class Fx {
  constructor(ctx) {
    this.ctx = ctx;
    this.group = new THREE.Group();
    this.group.name = 'fx';
    this.group.matrixAutoUpdate = false;

    // Read by CameraRig every frame — must exist before build().
    this.shake = { amount: 0, time: 0 };

    this.time = 0;
    this.enabled = true;

    const q = ctx?.engine?.qualityName ?? 'high';
    this.budget = QUALITY_BUDGET[q] ?? 1;

    // Deterministic per-seed stream, then a cheap local PRNG for the millions
    // of per-particle jitters that must not perturb world generation.
    const fork = ctx?.rng?.fork ? ctx.rng.fork('fx') : null;
    const s = fork ? (fork.int ? fork.int(1, 0x7ffffffe) : 12345) : 0x9e3779b9;
    this.rnd = mulberry32(s >>> 0);

    this.p = makeEmitParams();

    this._flame = { on: false, frac: 0, ring: 0, smoke: 0, light: 0, scorch: 0 };
    this._charge = { on: false, frac: 0, scuff: 0 };
    this._glide = { on: false, frac: 0 };
    this._trails = [];
    this._updrafts = [];
    this._handlers = [];
    this._origin = new THREE.Vector3();
    this._dir = new THREE.Vector3(0, 0, 1);
    this._fogColor = new THREE.Color(0xa9d4f2);
    this._registeredUpdrafts = false;
  }

  // ------------------------------------------------------------- lifecycle --

  async build() {
    this.atlas = makeSpriteAtlas(256);

    const scale = this.budget;
    this.addPool = new ParticlePool(this.atlas, Math.round(4200 * scale), true);
    this.alphaPool = new ParticlePool(this.atlas, Math.round(2600 * scale), false);
    this.group.add(this.addPool.mesh, this.alphaPool.mesh);

    // Pre-declared so the light count never changes at runtime.
    this.flameLight = new THREE.PointLight(FIRE_MID.getHex(), 0, 16, 2);
    this.flameLight.castShadow = false;
    this.flameLight.name = 'fx.flameLight';
    this.eventLight = new THREE.PointLight(0xffffff, 0, 14, 2);
    this.eventLight.castShadow = false;
    this.eventLight.name = 'fx.eventLight';
    this.group.add(this.flameLight, this.eventLight);
    this._eventLightT = 0;
    this._eventLightPeak = 0;

    this.ambient = new Ambient(this.addPool, this.alphaPool, this.p, this.rnd);
    this.ambient.density = this.budget;

    this._wire();
    this._registerWorldUpdrafts();

    return this.group;
  }

  _on(name, fn) {
    this.ctx.events.on(name, fn);
    this._handlers.push([name, fn]);
  }

  _wire() {
    const ctx = this.ctx;

    this._on('player:flame', (e) => {
      if (e && e.on) {
        this._flame.on = true;
        if (e.origin) this._origin.copy(e.origin);
        if (e.dir) this._dir.copy(e.dir);
        this._flame.ring = 0;
        // Immediate kick so the very first frame of the breath is already full.
        this.flameBurst(this._origin, this._dir, 0.9);
      } else {
        this._flame.on = false;
        this._flamePuffOut();
      }
