  /** Live particle accounting, for the health harness and debug overlays. */
  get stats() {
    return {
      addCapacity: this.addPool?.capacity ?? 0,
      alphaCapacity: this.alphaPool?.capacity ?? 0,
      emitted: (this.addPool?.emitted ?? 0) + (this.alphaPool?.emitted ?? 0),
      drawCalls: 2,
    };
  }

  dispose() {
    for (const [name, fn] of this._handlers) this.ctx.events.off(name, fn);
    this._handlers.length = 0;
    this._trails.length = 0;
    this._updrafts.length = 0;
    this.addPool?.dispose();
    this.alphaPool?.dispose();
    this.atlas?.dispose();
    if (this.flameLight) this.flameLight.dispose?.();
    if (this.eventLight) this.eventLight.dispose?.();
