/** Billboard orientation, packed into the instance data alongside the tile. */
export const MODE = {
  /** Camera-facing quad. The default for glows, puffs, sparks. */
  BILLBOARD: 0,
  /** Camera-facing, but local +Y follows screen-space velocity and stretches. */
  STRETCH: 1,
  /** Lies flat in the XZ plane. Shockwave rings, ground scuff, scorch smears. */
  GROUND: 2,
};

const FLOATS = 26;

/**
 * The emit descriptor. One shared, mutable instance is reused for every emit in
 * the game, which is what keeps the whole VFX layer allocation-free.
 */
export function makeEmitParams() {
  return {
    x: 0, y: 0, z: 0,
    vx: 0, vy: 0, vz: 0,
    life: 1,
    size0: 0.2,
    size1: 0.2,
    r0: 1, g0: 1, b0: 1,
    /** HDR multiplier on the start colour. > 1 pushes the particle into bloom. */
    intensity: 1,
    r1: 1, g1: 1, b1: 1,
    alpha: 1,
    rot: 0,
    spin: 0,
    tile: 0,
    mode: MODE.BILLBOARD,
    seed: 0,
    /** Linear drag coefficient, 1/s. ~0.5 floaty, ~4 snaps to a stop. */
    drag: 1,
    /** Constant vertical acceleration, m/s². Negative falls, positive rises. */
    gravity: 0,
    /** Amplitude of the per-particle wander, m/s. */
    turb: 0,
    /** World height the particle dissolves into. -9999 disables. */
    groundY: -9999,
  };
}

export function resetEmitParams(p) {
  p.x = p.y = p.z = 0;
  p.vx = p.vy = p.vz = 0;
  p.life = 1;
  p.size0 = p.size1 = 0.2;
  p.r0 = p.g0 = p.b0 = 1;
  p.intensity = 1;
  p.r1 = p.g1 = p.b1 = 1;
  p.alpha = 1;
  p.rot = 0;
  p.spin = 0;
  p.tile = 0;
  p.mode = MODE.BILLBOARD;
  p.seed = 0;
  p.drag = 1;
  p.gravity = 0;
  p.turb = 0;
  p.groundY = -9999;
  return p;
}

