import * as THREE from 'three';
import { Fx } from '../../../src/fx/Fx.js';
import { MODE } from '../../../src/fx/ParticlePool.js';
import { TILE } from '../../../src/fx/Textures.js';
import { mulberry32 } from '../../../src/core/Rng.js';

const TAU = Math.PI * 2;
const ORIGIN = { x: 1, y: 2, z: 3 };
const DIR = { x: 0, y: 0, z: 1 };
const BIOME = {
  accent: 0x42d17a,
  fog: { color: 0x8899aa },
};

function makeEmitter() {
  const calls = [];
  return {
    calls,
    emit(params, time) {
      calls.push({ ...params, time });
    },
  };
}

function makeFixture({
  enabled = true,
  withAddPool = true,
  withAlphaPool = true,
  budget = 1,
  ring = 100,
  scorch = 100,
  groundY = 0,
  withGroundSampler = true,
  biome = BIOME,
  flameLight = true,
} = {}) {
  const groundCalls = [];
  const world = withGroundSampler
    ? {
        sampleGround(x, z) {
          groundCalls.push([x, z]);
          return { y: groundY };
        },
      }
    : {};

  const fx = new Fx({ player: { biome }, world });
  fx.budget = budget;
  fx.time = 7.25;
  fx.enabled = enabled;
  fx.rnd = mulberry32(0xdecafbad);
  fx._flame = { on: false, frac: 0, ring, smoke: 0, light: 0, scorch };

  const add = makeEmitter();
  const alpha = makeEmitter();
  if (withAddPool) fx.addPool = add;
  if (withAlphaPool) fx.alphaPool = alpha;

  const lightPosition = {
    x: 0,
    y: 0,
    z: 0,
    set(x, y, z) {
      this.x = x;
      this.y = y;
      this.z = z;
    },
  };
  if (flameLight) fx.flameLight = { position: lightPosition };

  return { fx, add, alpha, groundCalls, world, lightPosition };
}

function familySlices(addCalls, n) {
  const jetCount = Math.max(1, Math.floor(n * 0.28));
  const emberCount = Math.max(1, Math.floor(n * 0.34));
  const coreEnd = n;
  const jetEnd = coreEnd + jetCount;
  const emberEnd = jetEnd + emberCount;
  return {
    core: addCalls.slice(0, coreEnd),
    jets: addCalls.slice(coreEnd, jetEnd),
    embers: addCalls.slice(jetEnd, emberEnd),
  };
}

function expectRgbClose(snapshot, prefix, expected, digits = 5) {
  expect(snapshot[`${prefix}r`]).toBeCloseTo(expected.r, digits);
  expect(snapshot[`${prefix}g`]).toBeCloseTo(expected.g, digits);
  expect(snapshot[`${prefix}b`]).toBeCloseTo(expected.b, digits);
}

describe('Fx.flameBurst', () => {
  describe('guards and fractional budget', () => {
    it('does nothing when the additive pool has not been built', () => {
      const { fx, add, alpha, groundCalls, lightPosition } = makeFixture({
        withAddPool: false,
      });
      const flameBefore = { ...fx._flame };
      lightPosition.set(4, 5, 6);

      fx.flameBurst(ORIGIN, DIR);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      expect(groundCalls).toHaveLength(0);
      expect(fx._flame).toEqual(flameBefore);
      expect([lightPosition.x, lightPosition.y, lightPosition.z]).toEqual([4, 5, 6]);
    });

    it('does nothing while disabled even when both pools exist', () => {
      const { fx, add, alpha } = makeFixture({ enabled: false });
      fx._flame.frac = 0.4;

      fx.flameBurst(ORIGIN, DIR);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      expect(fx._flame.frac).toBe(0.4);
      expect(fx._flame.ring).toBe(100);
      expect(fx._flame.light).toBe(0);
    });

    it('accumulates fractional emissions and returns without side effects below one particle', () => {
      const { fx, add, alpha, groundCalls, lightPosition } = makeFixture();

      fx.flameBurst(ORIGIN, DIR, 0.02);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      expect(groundCalls).toHaveLength(0);
      expect(fx._flame.frac).toBeCloseTo(0.76, 12);
      expect(fx._flame.ring).toBe(100);
      expect(fx._flame.light).toBe(0);
      expect([lightPosition.x, lightPosition.y, lightPosition.z]).toEqual([0, 0, 0]);

      fx.flameBurst(ORIGIN, DIR, 0.02);

