  describe('ring and ground scorch cadence', () => {
    it('emits a ring when its accumulator expires and implements its reset cadence', () => {
      const { fx, add } = makeFixture({ ring: 0.32 });
      const hot = new THREE.Color(0xfff4ce);
      const mid = new THREE.Color(0xffae33);

      // Three 0.1-strength quanta leave a positive accumulator; the fourth
