      const expectedGroundY = ORIGIN.y - 40 - 0.12;
      for (const p of [...core, ...jets, ...embers]) {
        expect(p.groundY).toBeCloseTo(expectedGroundY, 12);
      }
      expect(fx._flame.light).toBeCloseTo(0.14, 12);
    });

    it('raises the dominant flame light and positions the point light down the cone', () => {
      const { fx, lightPosition } = makeFixture();

      fx.flameBurst(ORIGIN, DIR);

      expect(fx._flame.light).toBeCloseTo(0.14, 12);
      expect(lightPosition.x).toBeCloseTo(ORIGIN.x, 12);
      expect(lightPosition.y).toBeCloseTo(ORIGIN.y + 0.2, 12);
      expect(lightPosition.z).toBeCloseTo(ORIGIN.z + 1.3, 12);
    });

    it('does not reduce an existing brighter flame light', () => {
      const { fx, lightPosition } = makeFixture();
      fx._flame.light = 0.9;

      fx.flameBurst(ORIGIN, DIR);

      expect(fx._flame.light).toBeCloseTo(0.9, 12);
      expect(lightPosition.z).toBeCloseTo(ORIGIN.z + 1.3, 12);
    });
  });
});
