      fx.flameBurst(ORIGIN, DIR);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      expect(groundCalls).toHaveLength(0);
      expect(fx._flame).toEqual(flameBefore);
      expect([lightPosition.x, lightPosition.y, lightPosition.z]).toEqual([4, 5, 6]);
    });

    it('does nothing while disabled even when both pools exist', () => {
      const { fx, add, alpha } = makeFixture({ enabled: false });
      fx._flame.frac = 0.4;

      fx.flameBurst(ORIGIN, DIR);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      expect(fx._flame.frac).toBe(0.4);
      expect(fx._flame.ring).toBe(100);
      expect(fx._flame.light).toBe(0);
    });

    it('accumulates fractional emissions and returns without side effects below one particle', () => {
      const { fx, add, alpha, groundCalls, lightPosition } = makeFixture();

      fx.flameBurst(ORIGIN, DIR, 0.02);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      // Ground under the tip is sampled before the fractional count is rounded.
      expect(groundCalls).toEqual([[ORIGIN.x, ORIGIN.z + 2.4]]);
      expect(fx._flame.frac).toBeCloseTo(0.76, 12);
      expect(fx._flame.ring).toBe(100);
      expect(fx._flame.light).toBe(0);
      expect([lightPosition.x, lightPosition.y, lightPosition.z]).toEqual([0, 0, 0]);

      fx.flameBurst(ORIGIN, DIR, 0.02);

      // One core particle, plus the minimum-one jet and ember particles, and
      // one smoke particle in the alpha pool.
      expect(add.calls).toHaveLength(3);
      expect(alpha.calls).toHaveLength(1);
      expect(fx._flame.frac).toBeCloseTo(0.52, 12);
      expect(fx._flame.light).toBeCloseTo(0.14, 12);

      fx.flameBurst(ORIGIN, DIR, 0.02);
      expect(add.calls).toHaveLength(6);
      expect(alpha.calls).toHaveLength(2);
      expect(fx._flame.frac).toBeCloseTo(0.28, 12);
    });

    it('returns without emitting for a zero strength and preserves the fraction', () => {
      const { fx, add, alpha } = makeFixture();
      fx._flame.frac = 0.5;

      fx.flameBurst(ORIGIN, DIR, 0);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      expect(fx._flame.frac).toBe(0.5);
      expect(fx._flame.ring).toBe(100);
      expect(fx._flame.light).toBe(0);
    });

    it('does not emit for a negative strength', () => {
      const { fx, add, alpha } = makeFixture();

      fx.flameBurst(ORIGIN, DIR, -3);

      expect(add.calls).toHaveLength(0);
      expect(alpha.calls).toHaveLength(0);
      expect(fx._flame.ring).toBe(100);
      expect(fx._flame.light).toBe(0);
    });
  });

