/**
 * Player physics and state machine.
 *
 * Tuned for the Spyro feel rather than realism: high gravity, near-instant
 * ground acceleration, a committed charge that you steer rather than stop, and
 * a glide that trades height for distance at a fixed, predictable rate so the
 * player can eyeball whether a gap is crossable.
 */
import * as THREE from 'three';
import { clamp, damp, lerp } from '../core/Rng.js';

const GRAVITY = -26;
const RUN_SPEED = 8.4;
const SPRINT_SPEED = 11.5;
const CHARGE_SPEED = 15.5;
const GROUND_ACCEL = 62;
const AIR_ACCEL = 22;
const JUMP_VELOCITY = 10.2;
const GLIDE_FALL = -3.1;
const GLIDE_SPEED = 10.5;
const HOVER_BOOST = 6.2;
const TURN_RATE = 11;
const GLIDE_TURN_RATE = 2.6;
const MAX_SLOPE = 0.82; // radians; steeper than this and you slide
const COYOTE_TIME = 0.13;
const JUMP_BUFFER = 0.14;
const PLAYER_RADIUS = 0.55;

const _v = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _fwd = new THREE.Vector3();
const _right = new THREE.Vector3();
const UP_AXIS = new THREE.Vector3(0, 1, 0);

export class Controller {
  constructor(ctx) {
    this.ctx = ctx;
    this.player = {
      position: new THREE.Vector3(),
      velocity: new THREE.Vector3(),
      forward: new THREE.Vector3(0, 0, 1),
      yaw: 0,
      state: 'ground',
      grounded: true,
      health: 4,
      maxHealth: 4,
      lives: 3,
      speed: 0,
      islandId: -1,
      biome: null,
      canGlide: false,
      groundNormal: new THREE.Vector3(0, 1, 0),
    };
    this.coyote = 0;
    this.jumpBuffer = 0;
    this.jumpCount = 0;
    this.glideTime = 0;
    this.hoverTime = 0;
    this.chargeTime = 0;
    this.flameTime = 0;
    this.hurtTime = 0;
    this.iframes = 0;
    this.deadTime = 0;
    this.lastGroundPos = new THREE.Vector3();
    this.turnInput = 0;
  }

  spawn(pos) {
    this.player.position.copy(pos);
    this.player.velocity.set(0, 0, 0);
    this.lastGroundPos.copy(pos);
    this.player.state = 'ground';
  }

  respawn(pos) {
    const p = pos || this.lastGroundPos;
    this.player.position.copy(p).add(new THREE.Vector3(0, 1.2, 0));
    this.player.velocity.set(0, 0, 0);
    this.player.state = 'air';
    this.jumpCount = 0;
    this.glideTime = 0;
    this.iframes = 1.2;
    this.ctx.events.emit('player:respawn', { position: this.player.position.clone() });
  }

  applyKnockback(dir, force) {
    this.player.velocity.addScaledVector(dir.clone().setY(0).normalize(), force);
    this.player.velocity.y = Math.max(this.player.velocity.y, force * 0.45);
  }

  hurt(amount = 1, sourcePos = null) {
    const p = this.player;
    if (this.iframes > 0 || p.state === 'dead') return false;
    p.health -= amount;
    this.iframes = 1.4;
    this.hurtTime = 0.5;
    if (sourcePos) {
      _v.subVectors(p.position, sourcePos).setY(0);
      if (_v.lengthSq() < 0.001) _v.set(0, 0, 1);
      this.applyKnockback(_v, 7);
    }
    this.ctx.events.emit('player:hurt', { position: p.position.clone(), source: sourcePos });
    if (p.health <= 0) this._die();
    else p.state = 'hurt';
    return true;
  }

  _die() {
    const p = this.player;
    p.state = 'dead';
    p.lives = Math.max(0, p.lives - 1);
    this.deadTime = 0;
    this.ctx.events.emit('player:die', { position: p.position.clone(), lives: p.lives });
  }

  /** Camera-relative desired direction from the raw stick input. */
  _desiredDir(out) {
    const { input, engine } = this.ctx;
    engine.camera.getWorldDirection(_fwd);
    _fwd.y = 0;

  _fwd.y = 0;
  if (_fwd.lengthSq() < 0.0001) _fwd.set(0, 0, 1);
  _fwd.normalize();
  // right = forward × up. For a Y-up right-handed system this already points
  // to the player's right; negating it swaps A and D.
  _right.crossVectors(_fwd, UP_AXIS).normalize();
  return out.set(0, 0, 0).addScaledVector(_fwd, input.move.y).addScaledVector(_right, input.move.x);
}

update(dt, ctx) {
  const p = this.player;
  const input = ctx.input;
  const world = ctx.world;

  this.iframes = Math.max(0, this.iframes - dt);
  this.coyote = Math.max(0, this.coyote - dt);
  this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);
  if (input.pressed('jump')) this.jumpBuffer = JUMP_BUFFER;

  if (p.state === 'dead') {
    this.deadTime += dt;
    p.velocity.y += GRAVITY * dt;
    p.position.addScaledVector(p.velocity, dt);
    const g = world.sampleGround(p.position.x, p.position.z);
    if (g && p.position.y < g.y) {
      p.position.y = g.y;
      p.velocity.set(0, 0, 0);
    }
    if (this.deadTime > 2.2) {
      if (p.lives > 0) {
        p.health = p.maxHealth;
        this.respawn(this.lastGroundPos);
      } else {
        ctx.events.emit('mission:failed', {});
        p.lives = 3;
        p.health = p.maxHealth;
        this.respawn(this.lastGroundPos);
      }
    }
    return;
  }

  const desired = this._desiredDir(_v2);
  const hasInput = desired.lengthSq() > 0.0001;
  if (hasInput) desired.normalize();

  // ---------------------------------------------------------- state ----
  const wantCharge = input.down('charge') && (p.state === 'ground' || p.state === 'charge');
  const wantFlame = input.pressed('flame');

  if (this.hurtTime > 0) {
    this.hurtTime -= dt;
    if (this.hurtTime <= 0 && p.state === 'hurt') p.state = p.grounded ? 'ground' : 'air';
  }

  if (this.flameTime > 0) {
    this.flameTime -= dt;
    if (this.flameTime <= 0) {
      ctx.events.emit('player:flame', { on: false });
      if (p.state === 'flame') p.state = p.grounded ? 'ground' : 'air';
    }
  } else if (wantFlame && p.state !== 'hurt' && p.state !== 'glide') {
    this.flameTime = 0.55;
    p.state = 'flame';
    const origin = new THREE.Vector3();
    if (ctx.dragon) ctx.dragon.mouthWorldPosition(origin);
    else origin.copy(p.position).addScaledVector(p.forward, 0.9).setY(p.position.y + 0.9);
    ctx.events.emit('player:flame', { on: true, origin, dir: p.forward.clone() });
  }

  // ------------------------------------------------------- horizontal ----
  let targetSpeed = 0;
  let accel = p.grounded ? GROUND_ACCEL : AIR_ACCEL;

  if (p.state === 'charge') {
    targetSpeed = CHARGE_SPEED;
    this.chargeTime += dt;
    // Charge steers, it doesn't stop. Release or hit something to exit.
    if (hasInput) {
      const targetYaw = Math.atan2(desired.x, desired.z);
      p.yaw = approachAngle(p.yaw, targetYaw, 3.4 * dt);
    }
    if (!input.down('charge') || this.chargeTime > 4) {
      p.state = p.grounded ? 'ground' : 'air';
      this.chargeTime = 0;
      ctx.events.emit('player:charge', { on: false });
    }
  } else if (wantCharge && p.grounded && hasInput) {
    p.state = 'charge';
    this.chargeTime = 0;
    ctx.events.emit('player:charge', { on: true });
    targetSpeed = CHARGE_SPEED;
  } else if (p.state === 'glide') {
    targetSpeed = GLIDE_SPEED;
    // Glide turns are wide and committed.
    this.turnInput = damp(this.turnInput, input.move.x, 8, dt);
    p.yaw -= this.turnInput * GLIDE_TURN_RATE * dt;
    if (input.move.y < -0.4) targetSpeed *= 0.72;
  } else if (p.state === 'flame') {
    targetSpeed = hasInput ? RUN_SPEED * 0.35 : 0;
