    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ down: { charge: true } }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'charge', grounded: true });
    controller.chargeTime = 3.95;

    controller.update(0.1, ctx);

    expect(player.state).toBe('ground');
    expect(controller.chargeTime).toBe(0);
    expect(events.payloads('player:charge')).toEqual([{ on: false }]);
  });

  test('releasing charge ends the charge', () => {
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ move: [0, 1] }),
    });
    pose(player, { state: 'charge', grounded: false });
