    expect(player.state).toBe('air');
    expect(controller.chargeTime).toBe(0);
    expect(events.payloads('player:charge')).toEqual([{ on: false }]);
  });

  test('charge target speed is the dedicated charge speed', () => {
    const ground = makeGround({ y: 0 });
    const { ctx, player } = (() => {
      const h = makeHarness({
