describe('Controller.update — dead state', () => {
  test('applies gravity, advances deadTime and ignores input while dead', () => {
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { jump: true, flame: true }, move: [0, 1] }),
    });
    pose(player, { position: [0, 10, 0], velocity: [0, 0, 0], state: 'dead', grounded: false });
    controller.deadTime = 0;

    controller.update(0.5, ctx);

    expect(controller.deadTime).toBeCloseTo(0.5, 10);
    // gravity for half a second
    expect(player.velocity.y).toBeCloseTo(GRAVITY * 0.5, 10);
    expect(player.position.y).toBeCloseTo(10 + GRAVITY * 0.5 * 0.5, 10);
    // the dead branch returns before any state-machine gameplay runs
    expect(events.names()).not.toContain('player:jump');
    expect(events.names()).not.toContain('player:flame');
    expect(player.state).toBe('dead');
  });

  test('the dead body settles on the ground instead of falling through it', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({ world: makeWorld({ ground }) });
    pose(player, { position: [0, -1, 0], velocity: [0, -4, 0], state: 'dead', grounded: false });

    controller.update(0.1, ctx);

    expect(player.position.y).toBe(0);
    expect(player.velocity.length()).toBe(0);
  });

  test('respawns with full health once the death timer passes 2.2s and lives remain', () => {
    const { controller, ctx, player, events } = makeHarness();
    pose(player, { position: [3, 4, 5], state: 'dead', grounded: false });
    player.lives = 1;
    player.health = 0;
    controller.deadTime = 2.1;
    controller.lastGroundPos.set(10, 2, -3);

    controller.update(0.2, ctx);

    expect(events.names()).toContain('player:respawn');
    expect(events.names()).not.toContain('mission:failed');
    expect(player.health).toBe(player.maxHealth);
    expect(player.state).toBe('air');
    expect(player.position.x).toBeCloseTo(10, 10);
    expect(player.position.y).toBeCloseTo(2 + 1.2, 10);
    expect(player.position.z).toBeCloseTo(-3, 10);
    expect(controller.iframes).toBeCloseTo(1.2, 10);
  });

  test('does not respawn at or below exactly 2.2s of dead time', () => {
    const { controller, ctx, player, events } = makeHarness();
    pose(player, { state: 'dead', grounded: false });
    player.lives = 2;
    controller.deadTime = 2.1;

    controller.update(0.05, ctx);

    expect(controller.deadTime).toBeCloseTo(2.15, 10);
    expect(events.names()).not.toContain('player:respawn');
    expect(player.state).toBe('dead');
  });

  test('emits mission:failed and restores three lives when the last life is lost', () => {
    const { controller, ctx, player, events } = makeHarness();
    pose(player, { state: 'dead', grounded: false });
    player.lives = 0;
    player.health = 0;
    controller.deadTime = 2.2;

    controller.update(0.05, ctx);

    expect(events.names()).toContain('mission:failed');
    expect(events.names()).toContain('player:respawn');
    expect(player.lives).toBe(3);
    expect(player.health).toBe(player.maxHealth);
  });
});

