  });

  test('charge steers toward the stick direction', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ down: { charge: true }, move: [1, 0] }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'charge', grounded: true, yaw: 0 });
    controller.chargeTime = 0.2;

    controller.update(0.016, ctx);

    // right of a +Z camera is -X, so the yaw must decrease toward -PI/2
    expect(player.yaw).toBeLessThan(0);
    expect(player.yaw).toBeGreaterThan(-Math.PI / 2);
    expect(controller.chargeTime).toBeGreaterThan(0.2);
  });

  test('a charge times out after 4 seconds and reports it stopped', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ down: { charge: true } }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'charge', grounded: true });
    controller.chargeTime = 3.95;

    controller.update(0.1, ctx);

    expect(player.state).toBe('ground');
    expect(controller.chargeTime).toBe(0);
    expect(events.payloads('player:charge')).toEqual([{ on: false }]);
  });

  test('releasing charge ends the charge', () => {
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ move: [0, 1] }),
    });
    pose(player, { state: 'charge', grounded: false });
    controller.chargeTime = 1;

    controller.update(0.016, ctx);

    expect(player.state).toBe('air');
    expect(controller.chargeTime).toBe(0);
    expect(events.payloads('player:charge')).toEqual([{ on: false }]);
  });

  test('charge target speed is the dedicated charge speed', () => {
    const ground = makeGround({ y: 0 });
    const { ctx, player } = (() => {
      const h = makeHarness({
        input: makeInput({ down: { charge: true }, move: [0, 1] }),
        world: makeWorld({ ground }),
      });
      pose(h.player, { position: [0, 0, 0], state: 'charge', grounded: true, yaw: 0 });
      h.controller.chargeTime = 0.1;
      return h;
    })();

    run(makeForward(ground), ctx, 60, 0.016);
    expect(player.speed).toBeGreaterThan(RUN_SPEED);
    expect(player.speed).toBeLessThanOrEqual(CHARGE_SPEED + 1e-6);
  });
});

// helper used above so the run loop shares the very same world/camera doubles
function makeForward() {
  return { update: () => {} };
}

/* ---------------------------------------------------------- flame state --- */

describe('Controller.update — flame breath', () => {
  test('starts a flame and reports the mouth origin when no dragon model exists', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true });

    controller.update(0.016, ctx);

    expect(controller.flameTime).toBeCloseTo(0.55, 10);
    expect(player.state).toBe('flame');
    const [flame] = events.payloads('player:flame');
    expect(flame.on).toBe(true);
    // fallback origin: one unit ahead and chest height
    expect(flame.origin.x).toBeCloseTo(0, 10);
    expect(flame.origin.y).toBeCloseTo(0.9, 10);
    expect(flame.origin.z).toBeCloseTo(0.9, 10);
    expect(flame.dir.x).toBeCloseTo(0, 10);
    expect(flame.dir.z).toBeCloseTo(1, 10);
  });

  test('uses the dragon mouth position when a dragon collaborator is present', () => {
    const ground = makeGround({ y: 0 });
    const dragon = { mouthWorldPosition: jest.fn((out) => out.set(4, 5, 6)) };
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
      world: makeWorld({ ground }),
      dragon,
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true });

    controller.update(0.016, ctx);

    expect(dragon.mouthWorldPosition).toHaveBeenCalledTimes(1);
    const [flame] = events.payloads('player:flame');
    expect(flame.origin.x).toBeCloseTo(4, 10);
    expect(flame.origin.y).toBeCloseTo(5, 10);
    expect(flame.origin.z).toBeCloseTo(6, 10);
  });

  test('the flame expires and the player returns to the ground state', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'flame', grounded: true });
    controller.flameTime = 0.05;

    controller.update(0.1, ctx);

    expect(controller.flameTime).toBeLessThanOrEqual(0);
    expect(player.state).toBe('ground');
    expect(events.payloads('player:flame')).toEqual([{ on: false }]);
  });

  test('cannot start a flame while hurt', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'hurt', grounded: true });
    controller.hurtTime = 0.4;

    controller.update(0.016, ctx);

    expect(controller.flameTime).toBe(0);
    expect(events.names()).not.toContain('player:flame');
  });

  test('cannot start a flame while gliding', () => {
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
    });
    pose(player, { state: 'glide', grounded: false });
    controller._hoverUsed = true;

    controller.update(0.016, ctx);

    expect(controller.flameTime).toBe(0);
    expect(events.names()).not.toContain('player:flame');
    expect(player.state).toBe('glide');
  });
});

/* ------------------------------------------------------- hurt behaviour --- */

describe('Controller.update — hurt state', () => {
  test('hurt state bleeds off horizontal speed', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'hurt', grounded: false, velocity: [5, 0, 0] });
    controller.hurtTime = 5;

    controller.update(0.016, ctx);

    expect(player.velocity.x).toBeGreaterThan(0);
    expect(player.velocity.x).toBeLessThan(5);
    expect(player.state).toBe('hurt');
  });

  test('hurt state recovers to ground when the hurt timer runs out on the ground', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({ world: makeWorld({ ground }) });
    pose(player, { position: [0, 0, 0], state: 'hurt', grounded: true, velocity: [0, 0, 0] });
    controller.hurtTime = 0.1;

    controller.update(0.2, ctx);

    expect(controller.hurtTime).toBeLessThanOrEqual(0);
    expect(player.state).toBe('ground');
  });

  test('hurt state recovers to air when the hurt timer runs out in mid-air', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'hurt', grounded: false, velocity: [0, 0, 0] });
    controller.hurtTime = 0.1;

    controller.update(0.2, ctx);

    expect(controller.hurtTime).toBeLessThanOrEqual(0);
    expect(player.state).toBe('air');
  });
});

/* -------------------------------------------------------- ground motion --- */

describe('Controller.update — horizontal movement', () => {
  test('accelerates up to run speed along the camera-relative stick direction', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [0, 1] }),
      world: makeWorld({ ground }),
      forward: [0, 0, 1],
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true, yaw: 0 });

    run(controller, ctx, 60, 0.016);

    expect(player.velocity.z).toBeCloseTo(RUN_SPEED, 3);
    expect(player.velocity.x).toBeCloseTo(0, 6);
    expect(player.speed).toBeCloseTo(RUN_SPEED, 3);
    expect(player.grounded).toBe(true);
  });

  test('uses the camera basis rather than world axes for direction', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [1, 0] }),
      world: makeWorld({ ground }),
      forward: [1, 0, 0], // camera looks down +X, so "right" is +Z
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true, yaw: 0 });

    run(controller, ctx, 60, 0.016);

    expect(player.velocity.z).toBeCloseTo(RUN_SPEED, 3);
    expect(Math.abs(player.velocity.x)).toBeLessThan(0.01);
  });

  test('partial stick deflection yields a proportionally slower run', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [0, 0.5] }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true, yaw: 0 });

    run(controller, ctx, 80, 0.016);

    const expected = RUN_SPEED * (0.35 + 0.65 * 0.5);
    expect(player.speed).toBeCloseTo(expected, 3);
    expect(player.speed).toBeLessThan(RUN_SPEED);
  });

  test('holding charge in the air sprints at sprint speed', () => {
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [0, 1], down: { charge: true } }),
    });
    pose(player, { state: 'air', grounded: false, yaw: 0 });

    run(controller, ctx, 80, 0.016);

    expect(player.state).toBe('air');
    expect(player.speed).toBeCloseTo(SPRINT_SPEED, 2);
    expect(player.speed).toBeGreaterThan(RUN_SPEED);
  });

  test('a standing player with no input coasts to a stop', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'air', grounded: false, velocity: [3, 0, 0] });

    run(controller, ctx, 80, 0.016);

    expect(player.speed).toBeLessThan(0.01);
  });
});

/* ------------------------------------------------------------ updrafts --- */

describe('Controller.update — updrafts', () => {
  const updraft = { x: 0, z: 0, r: 5, topY: 20, baseY: 0, strength: 100 };

  test('lifts an airborne player inside the shaft', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [0, 5, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    // gravity alone would leave -2.6; the shaft overcomes it
    expect(player.velocity.y).toBeGreaterThan(0);
    expect(player.velocity.y).toBeCloseTo(5.4, 6);
  });

  test('caps the lift at 17 m/s', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [{ ...updraft, strength: 1000 }] }),
    });
    pose(player, { position: [0, 5, 0], velocity: [0, 10, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBe(17);
  });

  test('a glide gets a stronger lift than an ordinary fall', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [0, 5, 0], velocity: [0, -3.1, 0], state: 'glide', grounded: false });
    controller._hoverUsed = true;

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBeCloseTo(-3.1 + 100 * 1.25 * 0.1, 6);
  });

  test('ignores shafts the player is outside of', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [100, 5, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBeCloseTo(GRAVITY * 0.1, 10);
  });

  test('ignores shafts the player has risen above', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [0, 25, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBeCloseTo(GRAVITY * 0.1, 10);
  });
});

