describe('Controller.update — falling out of the world', () => {
  test('falling below the kill plane damages the player and respawns them', () => {
    const { controller, ctx, player, events } = makeHarness({ killPlaneY: -50 });
    pose(player, { position: [0, -60, 0], velocity: [0, 0, 0], state: 'air', grounded: false });
    controller.lastGroundPos.set(5, 1, 5);

    controller.update(0.1, ctx);

    expect(player.health).toBe(3);
    expect(events.names()).toContain('player:hurt');
    expect(events.names()).toContain('player:respawn');
    expect(player.state).toBe('air');
    expect(player.position.x).toBeCloseTo(5, 10);
    expect(player.position.y).toBeCloseTo(1 + 1.2, 10);
    expect(player.position.z).toBeCloseTo(5, 10);
    expect(controller.iframes).toBeCloseTo(1.2, 10);
  });

  test('a lethal fall leaves the player dead instead of respawning immediately', () => {
    const { controller, ctx, player, events } = makeHarness({ killPlaneY: -50 });
    pose(player, { position: [0, -60, 0], velocity: [0, 0, 0], state: 'air', grounded: false });
    player.health = 1;
    player.lives = 2;

    controller.update(0.1, ctx);

    expect(player.state).toBe('dead');
    expect(player.lives).toBe(1);
    expect(events.names()).toContain('player:die');
    expect(events.names()).not.toContain('player:respawn');
  });

  test('invulnerability frames prevent fall damage but still recover the player', () => {
    const { controller, ctx, player, events } = makeHarness({ killPlaneY: -50 });
    pose(player, { position: [0, -60, 0], velocity: [0, 0, 0], state: 'air', grounded: false });
    controller.iframes = 0.5;

    controller.update(0.1, ctx);

    expect(player.health).toBe(4);
    expect(events.names()).not.toContain('player:hurt');
    expect(events.names()).toContain('player:respawn');
  });
});
