export const BIOME_IDS = Object.keys(BIOMES);

export function getBiome(id) {
  return BIOMES[id] || BIOMES.sunhaven;
}

/**
 * Choose the biome set for one run. The first island is always a bright,
 * readable biome so the player's first thirty seconds are legible; later
 * islands are drawn without repeats until the pool is exhausted.
 */
export function pickBiomeSequence(rng, count) {
  const openers = ['sunhaven', 'verdant', 'emberfall'];
  const first = rng.pick(openers);
  const rest = rng.shuffle(BIOME_IDS.filter((b) => b !== first));
  const out = [first];
  let i = 0;
  while (out.length < count) {
    out.push(rest[i % rest.length]);
    i++;
  }
  return out;
}

/** Gem colours are global — they must read identically in every biome. */
export const GEM_TIERS = [
  { value: 1, color: 0xf24a5c, name: 'red', scale: 0.55 },
